// Expanded regional catalogue. Cards are not a time or power scale.
const REGIONAL_ENTRIES=[{"id":"rx-carthage","title":"Carthage · Punic city and power","region":"africa","dates":"c. 9th century–146 BC","start":-850,"end":-146,"category":"history","location":"Gulf of Tunis · present-day Tunisia, with wider Mediterranean connections","note":"A Phoenician-founded city developed into a major North African and Mediterranean power. The start is an approximate ninth-century plotting anchor, not the legendary foundation year treated as certain. Roman destruction in 146 BC ended this selected Punic political phase; Roman Carthage later flourished on the site.","wikiTitle":"Ancient Carthage","sources":["regional_africa_carthage","wikipedia_rx-carthage"],"collections":["africa"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Ancient Carthage","url":"https://en.wikipedia.org/wiki/Ancient_Carthage","pageid":20663625}},{"id":"rx-amazigh","title":"Amazigh peoples · living cultures","region":"africa","dates":"20th century–present · selected modern frame","start":1901,"end":2027,"category":"culture","location":"North Africa · communities across several present-day states and diasporas","note":"A selected modern reading window for diverse Indigenous North African communities and languages, not a date for their origins. Amazigh histories long predate the medieval dynasties and modern borders. Living heritage includes Zenete Ahellil traditions in Gourara; no single state or uniform identity is implied.","wikiTitle":"Berbers","sources":["regional_africa_amazigh","regional_africa_ahellil","wikipedia_rx-amazigh"],"collections":["africa"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Berbers","url":"https://en.wikipedia.org/wiki/Berbers","pageid":48132}},{"id":"rx-almoravid","title":"Almoravid dynasty and realms","region":"africa","dates":"1056–1147 AD · conventional ruling phase","start":1056,"end":1147,"category":"history","location":"Western Sahara, Morocco, parts of Algeria and Iberia","note":"A Sanhaja Amazigh movement established a realm linking Saharan routes, the Maghrib and al-Andalus. Uses UNESCO’s 1056–1147 dynastic convention. Other chronologies begin with the earlier movement or the later consolidation around Marrakesh; territorial control changed considerably.","wikiTitle":"Almoravid dynasty","sources":["regional_africa_marrakesh","regional_africa_maghrib","wikipedia_rx-almoravid"],"collections":["africa"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Almoravid dynasty","url":"https://en.wikipedia.org/wiki/Almoravid_dynasty","pageid":1649}},{"id":"rx-almohad","title":"Almohad dynasty and realms","region":"africa","dates":"1147–1269 AD · Marrakesh ruling phase","start":1147,"end":1269,"category":"history","location":"Maghrib and al-Andalus · changing territories","note":"An Amazigh-led religious and political movement displaced Almoravid rule and expanded across the Maghrib. This window begins with the capture of Marrakesh, rather than the movement’s earlier beginnings. Its territorial losses and collapse unfolded in stages.","wikiTitle":"Almohad Caliphate","sources":["regional_africa_maghrib","regional_africa_marrakesh","wikipedia_rx-almohad"],"collections":["africa"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Almohad Caliphate","url":"https://en.wikipedia.org/wiki/Almohad_Caliphate","pageid":49867}},{"id":"rx-marinid","title":"Marinid Morocco","region":"africa","dates":"1269–1465 AD · selected consolidated phase","start":1269,"end":1465,"category":"history","location":"Centred on Fez · present-day Morocco, with wider campaigns","note":"The Marinids developed Fez and sponsored architecture and learning. The plotting window follows the Met’s consolidated Moroccan ruling phase after the fall of Marrakesh; the dynasty’s earlier rise began before 1269. It did not govern the entire Maghrib continuously.","wikiTitle":"Marinid Sultanate","sources":["regional_africa_maghrib","wikipedia_rx-marinid"],"collections":["africa"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Marinid dynasty","url":"https://en.wikipedia.org/wiki/Marinid_dynasty","pageid":1661433}},{"id":"rx-alaouite","title":"Alaouite dynasty","region":"africa","dates":"1666 AD–present · dynastic continuity","start":1666,"end":2027,"category":"history","location":"Morocco · changing political institutions and territorial authority","note":"A dynastic frame beginning with the conventional consolidation date. The continuation of the royal house is not uninterrupted independent government: French and Spanish protectorates overlapped it in the twentieth century. The modern constitutional state is a separate, overlapping reading.","wikiTitle":"Alawi dynasty","sources":["regional_africa_morocco-dynastic","regional_africa_morocco-modern","wikipedia_rx-alaouite"],"collections":["africa"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Alawi dynasty","url":"https://en.wikipedia.org/wiki/Alawi_dynasty","pageid":522695}},{"id":"rx-french-morocco","title":"Morocco · French protectorate","region":"africa","dates":"1912–1956 AD","start":1912,"end":1956,"category":"period","location":"Much of present-day Morocco · distinct from the Spanish zones and Tangier","note":"The Treaty of Fez established the French protectorate. Spanish-controlled zones and Tangier had different arrangements; this block does not put all Morocco under one French jurisdiction. Moroccan institutions and resistance continued, and independence was recognised in 1956.","wikiTitle":"French protectorate in Morocco","sources":["regional_africa_morocco-modern","wikipedia_rx-french-morocco"],"collections":["africa"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"French protectorate in Morocco","url":"https://en.wikipedia.org/wiki/French_protectorate_in_Morocco","pageid":785698}},{"id":"rx-morocco-modern","title":"Morocco · independent modern era","region":"africa","dates":"1956 AD–present","start":1956,"end":2027,"category":"history","location":"Northwest Africa · Morocco","note":"1956 marks the end of the French protectorate and recognition of independence, not the beginning of Moroccan society or monarchy. Decolonisation and territorial questions unfolded through several later stages; this date does not settle disputed boundaries.","wikiTitle":"Morocco","sources":["regional_africa_morocco-modern","wikipedia_rx-morocco-modern"],"collections":["africa"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Morocco","url":"https://en.wikipedia.org/wiki/Morocco","pageid":19291}},{"id":"rx-hausa-states","title":"Hausa states · late medieval and early modern","region":"africa","dates":"c. 1400–1804 AD · selected pre-jihad frame","start":1400,"end":1804,"category":"history","location":"Hausaland · principally present-day northern Nigeria and southern Niger","note":"Kano, Katsina, Zaria, Gobir and other states developed distinct courts, markets and political histories. This selected phase starts with their documented ascendancy by the fifteenth century and ends at the start of the Sokoto jihad. It is not one Hausa empire, nor a claim that every state began in 1400 or disappeared in 1804.","wikiTitle":"Hausa Kingdoms","sources":["regional_africa_hausa-history","regional_africa_sokoto-jihad","wikipedia_rx-hausa-states"],"collections":["africa"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Hausa Kingdoms","url":"https://en.wikipedia.org/wiki/Hausa_Kingdoms","pageid":4964227}},{"id":"rx-sokoto","title":"Sokoto Caliphate","region":"africa","dates":"1804–1903 AD","start":1804,"end":1903,"category":"history","location":"Central Sahel · principally present-day northern Nigeria and neighbouring regions","note":"A jihad beginning in 1804 transformed the regional political order and established a multiethnic network of emirates. Enslavement and slave labour were central to its economy. British conquest ended independent caliphal authority in 1903; communities and some emirate institutions continued under changed conditions.","wikiTitle":"Sokoto Caliphate","sources":["regional_africa_sokoto","regional_africa_sokoto-jihad","wikipedia_rx-sokoto"],"collections":["africa"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Sokoto Caliphate","url":"https://en.wikipedia.org/wiki/Sokoto_Caliphate","pageid":840510}},{"id":"rx-hausa-living","title":"Hausa communities · continuing histories","region":"africa","dates":"20th century–present · selected modern frame","start":1901,"end":2027,"category":"culture","location":"Northern Nigeria, southern Niger, wider West Africa and diasporas","note":"A selected modern window, not an origin date. Hausa-speaking communities continued through colonial rule and independence across state boundaries. Kano’s living Durbar traditions exemplify cultural transmission and adaptation; neither the Sokoto Caliphate nor colonial Nigeria contains the whole Hausa story.","wikiTitle":"Hausa people","sources":["regional_africa_kano-durbar","regional_africa_hausa-history","wikipedia_rx-hausa-living"],"collections":["africa"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Hausa people","url":"https://en.wikipedia.org/wiki/Hausa_people","pageid":11442998}},{"id":"rx-zulu-kingdom","title":"Zulu Kingdom · independent phase","region":"africa","dates":"c. 1816–1879 AD","start":1816,"end":1879,"category":"history","location":"Southeastern Africa · present-day KwaZulu-Natal, South Africa","note":"Shaka and subsequent rulers consolidated a kingdom through alliances and force. The dates delimit the selected independent political phase to British military defeat and partition. Later resistance and institutional changes continued; 1879 did not end Zulu people or culture.","wikiTitle":"Zulu Kingdom","sources":["regional_africa_zulu-archaeology","regional_africa_zulu-monarchy","wikipedia_rx-zulu-kingdom"],"collections":["africa"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Zulu Kingdom","url":"https://en.wikipedia.org/wiki/Zulu_Kingdom","pageid":14754726}},{"id":"rx-zulu-living","title":"Zulu communities · colonial and modern histories","region":"africa","dates":"1879 AD–present · selected continuity frame","start":1879,"end":2027,"category":"culture","location":"South Africa · especially KwaZulu-Natal, with wider communities","note":"This reading begins at the loss of the kingdom’s independence to make continuing history visible, not to date the origins of Zulu identity. Communities, isiZulu and royal institutions persisted through colonialism, apartheid and democratic South Africa. Language, cultural identity and political allegiance are not interchangeable.","wikiTitle":"Zulu people","sources":["regional_africa_zulu-monarchy","regional_africa_zulu-living","wikipedia_rx-zulu-living"],"collections":["africa"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Zulu people","url":"https://en.wikipedia.org/wiki/Zulu_people","pageid":34427}},{"id":"rx-madagascar-settlement","title":"Madagascar · early settlement networks","region":"africa","dates":"c. 600–1200 AD · selected archaeological phase","start":600,"end":1200,"category":"period","location":"Madagascar, the Comoros and western Indian Ocean connections","note":"Archaeology, crops, languages and ancestry reveal African and Southeast Asian contributions to Malagasy histories. Late-first- and early-second-millennium settlements provide an important evidence window. The first human arrival, earlier foraging evidence and the timing of different migrations remain debated; 600 is not a proven first landing, and 1200 is not an end to settlement.","wikiTitle":"History of Madagascar","sources":["regional_africa_madagascar-settlement","regional_africa_madagascar-review","wikipedia_rx-madagascar-settlement"],"collections":["africa"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"History of Madagascar","url":"https://en.wikipedia.org/wiki/History_of_Madagascar","pageid":50875}},{"id":"rx-maroserana","title":"Maroserana, Sakalava and Mahafaly kingdoms","region":"africa","dates":"c. 1600–1800 AD · selected formation phase","start":1600,"end":1800,"category":"history","location":"Western and southern Madagascar","note":"Maroserana-associated rulers consolidated several kingdoms, including Menabé and Boina, among diverse local communities. This selected seventeenth- and eighteenth-century window shows political formation and expansion, not a single island-wide state. The end of the window does not end Sakalava or Mahafaly communities and institutions.","wikiTitle":"Sakalava people","sources":["regional_africa_madagascar-kingdoms","wikipedia_rx-maroserana"],"collections":["africa"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Sakalava people","url":"https://en.wikipedia.org/wiki/Sakalava_people","pageid":4910346}},{"id":"rx-merina","title":"Merina kingdoms and Kingdom of Madagascar","region":"africa","dates":"c. 1600–1897 AD · changing kingdoms and monarchy","start":1600,"end":1897,"category":"history","location":"Central highlands and, later, much of Madagascar","note":"A broad frame for highland consolidation, subsequent division and late-eighteenth-century reunification, followed by wider expansion. Not all Madagascar was always under Merina control. France annexed the island in 1896; 1897 marks the monarchy’s final colonial removal, not the disappearance of Merina communities.","wikiTitle":"Merina Kingdom","sources":["regional_africa_madagascar-kingdoms","regional_africa_merina-archives","regional_africa_madagascar-archives","wikipedia_rx-merina"],"collections":["africa"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Imerina","url":"https://en.wikipedia.org/wiki/Imerina","pageid":18608397}},{"id":"rx-madagascar-colonial","title":"Madagascar · French colonial rule and transition","region":"africa","dates":"1896–1960 AD","start":1896,"end":1960,"category":"period","location":"Madagascar · changing colonial and autonomous arrangements","note":"French annexation in 1896 opened this selected colonial frame. Resistance, coercion and institutional change belong within it. The republic proclaimed in 1958 preceded full independence in 1960, so these dates do not describe one unchanging legal arrangement.","wikiTitle":"French Madagascar","sources":["regional_africa_madagascar-archives","regional_africa_madagascar-republic-archives","wikipedia_rx-madagascar-colonial"],"collections":["africa"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"French Madagascar","url":"https://en.wikipedia.org/wiki/French_Madagascar","pageid":37528205}},{"id":"rx-madagascar-modern","title":"Madagascar · independent eras","region":"africa","dates":"1960 AD–present","start":1960,"end":2027,"category":"history","location":"Madagascar · Indian Ocean","note":"Independence was proclaimed on 26 June 1960. This frame includes successive republican and political eras rather than one uninterrupted regime. Malagasy cultural histories extend across and before these modern constitutional boundaries.","wikiTitle":"Madagascar","sources":["regional_africa_madagascar-archives","regional_africa_ambohimanga","wikipedia_rx-madagascar-modern"],"collections":["africa"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Madagascar","url":"https://en.wikipedia.org/wiki/Madagascar","pageid":18964}},{"id":"rx-igbo-ukwu","title":"Igbo-Ukwu · archaeological metalwork","region":"africa","dates":"c. 9th–10th centuries AD","start":800,"end":1000,"category":"culture","location":"Southeastern Nigeria · Igbo-Ukwu","note":"Excavated ritual and burial contexts contain sophisticated copper-alloy vessels, regalia and imported beads. The range is an approximate archaeological plotting window; the ninth-century dating has been debated. It does not identify a documented empire or date the beginning or end of Igbo history.","wikiTitle":"Igbo-Ukwu","sources":["regional_africa_igbo-ukwu","regional_africa_igbo-ukwu-bm","wikipedia_rx-igbo-ukwu"],"collections":["africa"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Igbo-Ukwu","url":"https://en.wikipedia.org/wiki/Igbo-Ukwu","pageid":3590424}},{"id":"rx-swahili-living","title":"Swahili peoples and coastal cultures","region":"africa","dates":"c. 9th century AD–present · broad cultural frame","start":800,"end":2027,"category":"culture","location":"East African coast, islands and wider Indian Ocean connections","note":"A broad reading frame for African coastal communities participating in Indian Ocean exchange, not a single empire. Kilwa is one selected city, not the whole coast. Coastal cultures and Kiswahili-speaking communities continued through Portuguese, Omani and European colonial interventions and remain living traditions, as at Lamu.","wikiTitle":"Swahili people","sources":["regional_africa_kilwa","regional_africa_lamu","wikipedia_rx-swahili-living"],"collections":["africa"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Swahili people","url":"https://en.wikipedia.org/wiki/Swahili_people","pageid":1543991}},{"id":"rx-yoruba-living","title":"Yoruba communities · living cultures","region":"africa","dates":"20th century–present · selected modern frame","start":1901,"end":2027,"category":"culture","location":"Nigeria, Benin, Togo and wider diasporas","note":"A selected modern reading window, not an origin date. Yoruba histories extend beyond the political phases of Ife and Oyo. Osun-Osogbo’s living sacred landscape and evolving annual festival are one example of continuing cultural practice; no single faith or state represents all Yoruba people.","wikiTitle":"Yoruba people","sources":["regional_africa_yoruba","regional_africa_gelede","wikipedia_rx-yoruba-living"],"collections":["africa"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Yoruba people","url":"https://en.wikipedia.org/wiki/Yoruba_people","pageid":19996678}},{"id":"rx-edo-living","title":"Edo communities · continuing Benin traditions","region":"africa","dates":"1897 AD–present · selected continuity frame","start":1897,"end":2027,"category":"culture","location":"Benin City and wider Edo communities · Nigeria and diasporas","note":"The selected frame begins with British conquest and looting to show that Edo society and artistic traditions continued afterwards. The cultural community and royal institution are not the same as the formerly independent state. This is unrelated to the modern Republic of Benin’s name.","wikiTitle":"Edo people","sources":["regional_africa_edo","wikipedia_rx-edo-living"],"collections":["africa"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Edo people","url":"https://en.wikipedia.org/wiki/Edo_people","pageid":13609806}},{"id":"rx-shona-living","title":"Shona communities · living cultures","region":"africa","dates":"20th century–present · selected modern frame","start":1901,"end":2027,"category":"culture","location":"Zimbabwe and neighbouring countries, with wider diasporas","note":"A selected modern window, not a date for the origins of Shona communities. Great Zimbabwe’s medieval urban phase is one part of a longer regional history. Living mbira traditions illustrate continuity and change, and are also practised by communities other than Shona; no uniform state or unchanging identity is implied.","wikiTitle":"Shona people","sources":["regional_africa_shona","wikipedia_rx-shona-living"],"collections":["africa"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Shona people","url":"https://en.wikipedia.org/wiki/Shona_people","pageid":2173526}},{"id":"rx-toltec","title":"Tula · Toltec traditions","region":"americas","dates":"c. 900–1150 AD · principal Tollan phase","start":900,"end":1150,"category":"history","location":"Central Mexico · present-day Hidalgo","note":"Tula was a major urban and political centre with craft neighbourhoods and far-reaching exchanges. This dates its principal Tollan phase, not all occupation at Tula. The extent and nature of Toltec political control and the interpretation of later Tollan narratives remain debated; shared styles do not establish a single empire across Mesoamerica.","wikiTitle":"Toltec","sources":["regional_americas_pacific_tula","regional_americas_pacific_toltec-research","wikipedia_rx-toltec"],"collections":["americas"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Toltec","url":"https://en.wikipedia.org/wiki/Toltec","pageid":45522}},{"id":"rx-monte-alban","title":"Monte Albán · Zapotec capital","region":"americas","dates":"c. 500 BC–850 AD · principal capital phase","start":-500,"end":850,"category":"history","location":"Valley of Oaxaca · present-day Mexico","note":"A major Zapotec capital developed monumental terraces, plazas, tombs and inscriptions. The dates select the main capital phase. Later use of the site and the histories of Zapotec and Mixtec communities extend beyond it; a city’s decline did not end a people.","wikiTitle":"Monte Albán","sources":["regional_americas_pacific_monte-alban","wikipedia_rx-monte-alban"],"collections":["americas"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Monte Albán","url":"https://en.wikipedia.org/wiki/Monte_Alb%C3%A1n","pageid":355462}},{"id":"rx-mixtec-polities","title":"Mixtec kingdoms · Postclassic era","region":"americas","dates":"c. 900–1521 AD · selected regional frame","start":900,"end":1521,"category":"history","location":"Oaxaca, Puebla and Guerrero · present-day Mexico","note":"Multiple Mixtec lordships developed dynastic histories, alliances and artistic traditions. This conventional Postclassic frame groups distinct polities and overlapping Zapotec histories; it does not describe a single Mixtec empire or the end of Mixtec life at conquest.","wikiTitle":"Mixtec culture","sources":["regional_americas_pacific_mixtec-history","wikipedia_rx-mixtec-polities"],"collections":["americas"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Mixtec culture","url":"https://en.wikipedia.org/wiki/Mixtec_culture","pageid":70493156}},{"id":"rx-zapotec-peoples","title":"Zapotec peoples · living communities","region":"americas","dates":"Ancestral roots–present","start":null,"end":2027,"category":"culture","location":"Oaxaca and wider diasporas · Mexico and beyond","note":"Distinct Zapotec communities maintain languages, institutions, traditions and new forms of cultural life. Colonial and national rule transformed their circumstances without ending their histories. There is no single founding year or one uniform Zapotec identity.","wikiTitle":"Zapotec peoples","sources":["regional_americas_pacific_zapotec-living","wikipedia_rx-zapotec-peoples"],"collections":["americas"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Zapotec peoples","url":"https://en.wikipedia.org/wiki/Zapotec_peoples","pageid":147246}},{"id":"rx-mixtec-peoples","title":"Ñuu Savi / Mixtec peoples · living communities","region":"americas","dates":"Ancestral roots–present","start":null,"end":2027,"category":"culture","location":"Oaxaca, Guerrero, Puebla and wider diasporas","note":"Mixtec communities continue across their homelands and migrant networks, sustaining varied languages and practices. This entry concerns living peoples; the separately listed Postclassic kingdoms are a selected political phase, not the whole history of Ñuu Savi.","wikiTitle":"Mixtec","sources":["regional_americas_pacific_mixtec-living","wikipedia_rx-mixtec-peoples"],"collections":["americas"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Mixtec","url":"https://en.wikipedia.org/wiki/Mixtec","pageid":195744}},{"id":"rx-chavin","title":"Chavín · ceremonial traditions","region":"americas","dates":"c. 1500–300 BC · broad heritage range","start":-1500,"end":-300,"category":"culture","location":"North-central Peruvian Andes","note":"Chavín de Huántar was a ceremonial and pilgrimage centre whose imagery and religious networks circulated widely. The broad range follows UNESCO’s introductory chronology; construction phases and regional chronologies differ. Cultural influence does not by itself demonstrate a territorial empire.","wikiTitle":"Chavín culture","sources":["regional_americas_pacific_chavin","wikipedia_rx-chavin"],"collections":["americas"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Chavín culture","url":"https://en.wikipedia.org/wiki/Chav%C3%ADn_culture","pageid":1227304}},{"id":"rx-taino","title":"Taíno heritage · continuing communities","region":"americas","dates":"Ancestral roots–present","start":null,"end":2027,"category":"culture","location":"Caribbean · including Cuba, Hispaniola, Puerto Rico and diasporas","note":"Colonial disease, enslavement and violence devastated Indigenous Caribbean societies. Descendants, families and community organisations nevertheless sustain and renew Taíno heritage and identities. The common claim of total extinction is misleading; identities and experiences differ across islands and communities.","wikiTitle":"Taíno","sources":["regional_americas_pacific_taino","wikipedia_rx-taino"],"collections":["americas"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Taíno","url":"https://en.wikipedia.org/wiki/Ta%C3%ADno","pageid":31998621}},{"id":"rx-poverty-point","title":"Poverty Point · hunter-fisher-gatherer earthworks","region":"americas","dates":"c. 1700–1100 BC","start":-1700,"end":-1100,"category":"history","location":"Lower Mississippi Valley · present-day Louisiana, United States","note":"Hunter-fisher-gatherers created an extensive earthwork landscape used for residence and ceremony. Monumental construction and long-distance exchange were possible without a farming empire. These dates describe the principal site, not the beginning or end of Indigenous history in the lower Mississippi Valley.","wikiTitle":"Poverty Point","sources":["regional_americas_pacific_poverty-point","wikipedia_rx-poverty-point"],"collections":["americas"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Poverty Point","url":"https://en.wikipedia.org/wiki/Poverty_Point","pageid":30872722}},{"id":"rx-hopewell","title":"Hopewell · ceremonial and exchange networks","region":"americas","dates":"c. 200 BC–500 AD","start":-200,"end":500,"category":"culture","location":"Eastern North America · especially the Ohio valleys","note":"Communities built geometric earthworks and exchanged materials across extensive networks. Hopewell is an archaeological label derived from a later landowner, not a known Indigenous nation’s own name or one empire. The date range is a broad Ohio Valley convention.","wikiTitle":"Hopewell tradition","sources":["regional_americas_pacific_hopewell","regional_americas_pacific_hopewell-dates","wikipedia_rx-hopewell"],"collections":["americas"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Hopewell tradition","url":"https://en.wikipedia.org/wiki/Hopewell_tradition","pageid":313110}},{"id":"rx-mapuche","title":"Mapuche · continuing peoples and cultures","region":"americas","dates":"Ancestral roots–present","start":null,"end":2027,"category":"culture","location":"South-central Chile and neighbouring Argentina · wider diasporas","note":"Mapuche communities continue their languages, place-based knowledge and varied political and cultural practices. Their history extends through resistance, changing relationships with colonial and national states, dispossession and contemporary renewal. This is no single kingdom or founding date.","wikiTitle":"Mapuche","sources":["regional_americas_pacific_mapuche","regional_americas_pacific_mapuche-location","wikipedia_rx-mapuche"],"collections":["americas"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Mapuche","url":"https://en.wikipedia.org/wiki/Mapuche","pageid":392305}},{"id":"rx-guarani","title":"Guaraní peoples · continuing communities","region":"americas","dates":"Ancestral roots–present","start":null,"end":2027,"category":"culture","location":"South America · including Paraguay, Brazil and neighbouring countries","note":"Guaraní identifies multiple related Indigenous peoples and languages, rather than one state. Living communities maintain and adapt knowledge, institutions and cultural practices. Colonial mission histories form only one part of those histories and do not mark their beginning or end.","wikiTitle":"Guaraní people","sources":["regional_americas_pacific_guarani","regional_americas_pacific_guarani-history","wikipedia_rx-guarani"],"collections":["americas"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Guaraní people","url":"https://en.wikipedia.org/wiki/Guaran%C3%AD_people","pageid":100754}},{"id":"rx-central-american-federation","title":"Central American Federation","region":"americas","dates":"1823–early 1840s · gradual dissolution","start":1823,"end":1841,"category":"history","location":"Guatemala, El Salvador, Honduras, Nicaragua and Costa Rica","note":"The United Provinces formed after separation from Mexico in 1823 and adopted a federal constitution in 1824. Civil conflict and secessions broke the union apart from 1838 onward. 1841 is a rounded endpoint for a gradual process, not a single simultaneous independence date for all five states.","wikiTitle":"Federal Republic of Central America","sources":["regional_americas_pacific_federation","regional_americas_pacific_central-declaration","wikipedia_rx-central-american-federation"],"collections":["americas"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Federal Republic of Central America","url":"https://en.wikipedia.org/wiki/Federal_Republic_of_Central_America","pageid":196323}},{"id":"rx-bolivia","title":"Bolivia · independent eras","region":"americas","dates":"1825–present","start":1825,"end":2027,"category":"history","location":"South America · Andean highlands and eastern lowlands","note":"Bolivia declared independence in 1825. Its later history includes the Peru–Bolivian Confederation and changing constitutional and political orders. This state-history frame does not date the origins of the region’s Indigenous peoples.","wikiTitle":"Bolivia","sources":["regional_americas_pacific_bolivia","wikipedia_rx-bolivia"],"collections":["americas"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Bolivia","url":"https://en.wikipedia.org/wiki/Bolivia","pageid":3462}},{"id":"rx-uruguay","title":"Uruguay · independent state eras","region":"americas","dates":"1828–present · declaration in 1825","start":1828,"end":2027,"category":"history","location":"Río de la Plata · southeastern South America","note":"An 1825 declaration preceded the 1828 settlement securing a separate Uruguayan state after war with Brazil. The constitution followed in 1830. These political milestones are distinct from earlier histories of the region and its peoples.","wikiTitle":"Uruguay","sources":["regional_americas_pacific_uruguay","wikipedia_rx-uruguay"],"collections":["americas"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Uruguay","url":"https://en.wikipedia.org/wiki/Uruguay","pageid":31843}},{"id":"rx-paraguay","title":"Paraguay · independent eras","region":"americas","dates":"1811–present","start":1811,"end":2027,"category":"history","location":"South America · Paraguay River region and Chaco","note":"Paraguay asserted independence in 1811; wider international recognition came later. This frame groups changing governments and borders. Guaraní and other Indigenous histories are not reducible to the modern state’s founding.","wikiTitle":"Paraguay","sources":["regional_americas_pacific_paraguay","wikipedia_rx-paraguay"],"collections":["americas"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Paraguay","url":"https://en.wikipedia.org/wiki/Paraguay","pageid":23420}},{"id":"rx-guatemala","title":"Guatemala · postcolonial state eras","region":"americas","dates":"1821–present · includes Mexican and federal phases","start":1821,"end":2027,"category":"history","location":"Central America","note":"Regional independence from Spain in 1821 was followed by Mexican rule and membership in the Central American federation. Guatemala’s separate statehood consolidated as the federation dissolved; U.S. recognition followed in 1844. This broad frame is not a claim of uninterrupted separate sovereignty from 1821, and does not date the origins of its peoples.","wikiTitle":"Guatemala","sources":["regional_americas_pacific_guatemala","regional_americas_pacific_central-declaration","wikipedia_rx-guatemala"],"collections":["americas"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Guatemala","url":"https://en.wikipedia.org/wiki/Guatemala","pageid":17238567}},{"id":"rx-honduras","title":"Honduras · postcolonial state eras","region":"americas","dates":"1821–present · includes Mexican and federal phases","start":1821,"end":2027,"category":"history","location":"Central America","note":"Regional independence from Spain in 1821 was followed by Mexican rule and membership in the Central American federation. Honduras became a separate state as the federation dissolved in 1838. This broad frame is not a claim of uninterrupted separate sovereignty from 1821, and does not date the origins of its peoples.","wikiTitle":"Honduras","sources":["regional_americas_pacific_honduras","regional_americas_pacific_central-declaration","wikipedia_rx-honduras"],"collections":["americas"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Honduras","url":"https://en.wikipedia.org/wiki/Honduras","pageid":13394}},{"id":"rx-el-salvador","title":"El Salvador · postcolonial state eras","region":"americas","dates":"1821–present · includes Mexican and federal phases","start":1821,"end":2027,"category":"history","location":"Central America","note":"Regional independence from Spain in 1821 was followed by Mexican rule and membership in the Central American federation. El Salvador’s 1841 constitution followed the federation’s collapse. This broad frame is not a claim of uninterrupted separate sovereignty from 1821, and does not date the origins of its peoples.","wikiTitle":"El Salvador","sources":["regional_americas_pacific_el-salvador","regional_americas_pacific_central-declaration","regional_americas_pacific_el-salvador-constitution","wikipedia_rx-el-salvador"],"collections":["americas"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"El Salvador","url":"https://en.wikipedia.org/wiki/El_Salvador","pageid":9356}},{"id":"rx-nicaragua","title":"Nicaragua · postcolonial state eras","region":"americas","dates":"1821–present · includes Mexican and federal phases","start":1821,"end":2027,"category":"history","location":"Central America","note":"Regional independence from Spain in 1821 was followed by Mexican rule and membership in the Central American federation. Nicaragua separated from the federation in 1838. This broad frame is not a claim of uninterrupted separate sovereignty from 1821, and does not date the origins of its peoples.","wikiTitle":"Nicaragua","sources":["regional_americas_pacific_nicaragua","regional_americas_pacific_central-declaration","wikipedia_rx-nicaragua"],"collections":["americas"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Nicaragua","url":"https://en.wikipedia.org/wiki/Nicaragua","pageid":21362}},{"id":"rx-costa-rica","title":"Costa Rica · postcolonial state eras","region":"americas","dates":"1821–present · includes Mexican and federal phases","start":1821,"end":2027,"category":"history","location":"Central America","note":"Regional independence from Spain in 1821 was followed by Mexican rule and membership in the Central American federation. Costa Rica separated from the federation in 1838 and proclaimed its republic in 1848. This broad frame is not a claim of uninterrupted separate sovereignty from 1821, and does not date the origins of its peoples.","wikiTitle":"Costa Rica","sources":["regional_americas_pacific_costa-rica","regional_americas_pacific_central-declaration","regional_americas_pacific_costa-rica-state","wikipedia_rx-costa-rica"],"collections":["americas"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Costa Rica","url":"https://en.wikipedia.org/wiki/Costa_Rica","pageid":5551}},{"id":"rx-belize","title":"Belize · independent state","region":"americas","dates":"1981–present","start":1981,"end":2027,"category":"history","location":"Caribbean coast of Central America","note":"Belize became independent from the United Kingdom on 21 September 1981 after earlier British colonial rule and self-government. This dates the modern state, not its Maya, Garifuna, Creole and other communities’ beginnings.","wikiTitle":"Belize","sources":["regional_americas_pacific_belize","wikipedia_rx-belize"],"collections":["americas"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Belize","url":"https://en.wikipedia.org/wiki/Belize","pageid":3458}},{"id":"rx-cuba","title":"Cuba · republic and later eras","region":"americas","dates":"1902–present","start":1902,"end":2027,"category":"history","location":"Caribbean · Cuba","note":"The republic began in 1902 after Spanish sovereignty ended in 1898 and U.S. military occupation followed. U.S. intervention rights constrained early sovereignty. The 1959 revolution brought a major political transformation; these are different eras within a longer Cuban history.","wikiTitle":"Cuba","sources":["regional_americas_pacific_cuba","wikipedia_rx-cuba"],"collections":["americas"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Cuba","url":"https://en.wikipedia.org/wiki/Cuba","pageid":5042481}},{"id":"rx-dominican-republic","title":"Dominican Republic · independent eras","region":"americas","dates":"1844–present · sovereignty interrupted","start":1844,"end":2027,"category":"history","location":"Eastern Hispaniola · Caribbean","note":"Independence from Haiti was declared in 1844. Spanish annexation interrupted sovereignty in 1861–1865; later U.S. occupations also shaped state history. The broad frame does not imply one uninterrupted political order or the disappearance of Indigenous Caribbean heritage.","wikiTitle":"Dominican Republic","sources":["regional_americas_pacific_dominican-republic","wikipedia_rx-dominican-republic"],"collections":["americas"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Dominican Republic","url":"https://en.wikipedia.org/wiki/Dominican_Republic","pageid":8060}},{"id":"rx-guyana","title":"Guyana · independent state","region":"americas","dates":"1966–present","start":1966,"end":2027,"category":"history","location":"Northeastern South America","note":"Guyana became independent from the United Kingdom in 1966, following British Guiana. This dates a state transition; the histories of Indigenous nations and the country’s other communities extend much further back.","wikiTitle":"Guyana","sources":["regional_americas_pacific_guyana","wikipedia_rx-guyana"],"collections":["americas"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Guyana","url":"https://en.wikipedia.org/wiki/Guyana","pageid":17238691}},{"id":"rx-suriname","title":"Suriname · independent state","region":"americas","dates":"1975–present","start":1975,"end":2027,"category":"history","location":"Northeastern South America","note":"Suriname became independent from the Netherlands in 1975 after increasing autonomy. This state-history frame does not compress its Indigenous peoples, Maroon communities and other populations into a single political origin.","wikiTitle":"Suriname","sources":["regional_americas_pacific_suriname","wikipedia_rx-suriname"],"collections":["americas"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Suriname","url":"https://en.wikipedia.org/wiki/Suriname","pageid":26828}},{"id":"rx-hawaiian-kingdom","title":"Kingdom of Hawaiʻi","region":"oceania","dates":"1795–1893 · island consolidation completed 1810","start":1795,"end":1893,"category":"history","location":"Hawaiian archipelago · North Pacific","note":"Kamehameha consolidated most major islands in the 1790s; Kauaʻi’s ruler accepted his supremacy in 1810. The monarchy was overthrown in 1893 under duress, with U.S. involvement. These dates describe the royal state, not the duration of Native Hawaiian people or culture.","wikiTitle":"Hawaiian Kingdom","sources":["regional_americas_pacific_hawaii","regional_americas_pacific_hawaii-overthrow","regional_americas_pacific_hawaii-us-role","wikipedia_rx-hawaiian-kingdom"],"collections":["oceania"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Hawaiian Kingdom","url":"https://en.wikipedia.org/wiki/Hawaiian_Kingdom","pageid":23363583}},{"id":"rx-native-hawaiians","title":"Kānaka Maoli / Native Hawaiians · continuing community","region":"oceania","dates":"Ancestral roots–present","start":null,"end":2027,"category":"culture","location":"Hawaiʻi and wider diasporas","note":"Native Hawaiian communities continue their languages, genealogies, cultural practices and relationships with land and sea. The monarchy’s overthrow and subsequent U.S. annexation did not end this Indigenous community. Questions of sovereignty and political status have continuing historical significance.","wikiTitle":"Native Hawaiians","sources":["regional_americas_pacific_hawaiian-living","regional_americas_pacific_hawaii-overthrow","wikipedia_rx-native-hawaiians"],"collections":["oceania"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Native Hawaiians","url":"https://en.wikipedia.org/wiki/Native_Hawaiians","pageid":681745}},{"id":"rx-papua-new-guinea","title":"Papua New Guinea · independent state","region":"oceania","dates":"1975–present","start":1975,"end":2027,"category":"history","location":"Eastern New Guinea and neighbouring islands","note":"Papua New Guinea became independent from Australia on 16 September 1975 after self-government in 1973. The modern state brought together territories with different colonial histories and many distinct peoples and languages. It comprises eastern New Guinea and adjacent islands, not the entire island of New Guinea.","wikiTitle":"Papua New Guinea","sources":["regional_americas_pacific_png","regional_americas_pacific_png-independence","wikipedia_rx-papua-new-guinea"],"collections":["oceania"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Papua New Guinea","url":"https://en.wikipedia.org/wiki/Papua_New_Guinea","pageid":22943}},{"id":"rx-samoa","title":"Samoa · independent state","region":"oceania","dates":"1962–present","start":1962,"end":2027,"category":"history","location":"Western Samoan islands · central Pacific","note":"Western Samoa became independent from New Zealand administration in 1962 and later adopted the name Samoa. This state is distinct from American Samoa. Samoan societies and cultural histories substantially predate these changes in political status.","wikiTitle":"Samoa","sources":["regional_americas_pacific_samoa","wikipedia_rx-samoa"],"collections":["oceania"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Samoa","url":"https://en.wikipedia.org/wiki/Samoa","pageid":27238}},{"id":"rx-vanuatu","title":"Vanuatu · independent state","region":"oceania","dates":"1980–present","start":1980,"end":2027,"category":"history","location":"Melanesia · southwestern Pacific","note":"Vanuatu became independent on 30 July 1980 after the Anglo-French New Hebrides condominium. Its many communities developed distinct languages and kastom long before colonial administration. Independence is a state milestone, not their beginning.","wikiTitle":"Vanuatu","sources":["regional_americas_pacific_vanuatu","wikipedia_rx-vanuatu"],"collections":["oceania"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Vanuatu","url":"https://en.wikipedia.org/wiki/Vanuatu","pageid":32443}},{"id":"rx-solomon-islands","title":"Solomon Islands · independent state","region":"oceania","dates":"1978–present","start":1978,"end":2027,"category":"history","location":"Melanesia · southwestern Pacific","note":"Solomon Islands became independent on 7 July 1978 after internal self-government in 1976. This dates the modern state and does not cover all earlier island societies. The sovereign country is not identical to the whole geographical Solomon archipelago.","wikiTitle":"Solomon Islands","sources":["regional_americas_pacific_solomon","wikipedia_rx-solomon-islands"],"collections":["oceania"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Solomon Islands","url":"https://en.wikipedia.org/wiki/Solomon_Islands","pageid":265083}},{"id":"rx-human-origins","title":"Homo sapiens · African origins","region":"africa","dates":"By about 300,000 years ago","start":null,"end":null,"category":"Human origins","location":"Africa · evidence from several regions","wikiTitle":"Homo sapiens","note":"Our species emerged in Africa long before kingdoms or writing. Around 300,000 years is an approximate fossil-based age, not an exact birthday or a single founding community. Earlier human relatives extend much farther into the past; Homo sapiens continues today. Numeric BC boundaries are omitted to avoid false precision.","sources":["regional_deep_past_sapiens","wikipedia_rx-human-origins"],"collections":["early-world","africa"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Human","url":"https://en.wikipedia.org/wiki/Human","pageid":682482}},{"id":"rx-early-migrations","title":"Early human migrations","region":null,"dates":"Pleistocene · repeated movements","start":null,"end":null,"category":"Human origins","location":"Within Africa and across Eurasia, Sahul and the Americas","wikiTitle":"Early human migrations","note":"Movement occurred in many episodes, not one march along a single arrow. Fossils, archaeology and genetics illuminate dispersals and contacts; arrival dates and routes remain debated. This overview includes earlier human relatives as well as Homo sapiens. Later settlement of many Pacific islands belongs to a different, much more recent history.","sources":["regional_deep_past_migrations","wikipedia_rx-early-migrations"],"collections":["early-world"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Early human migrations","url":"https://en.wikipedia.org/wiki/Early_human_migrations","pageid":14821485}},{"id":"rx-foraging-lifeways","title":"Foraging, fishing & mixed economies","region":null,"dates":"Deep prehistory–present · diverse traditions","start":null,"end":null,"ongoing":true,"category":"Living traditions","location":"Many regions · no single society or universal sequence","wikiTitle":"Hunter-gatherer","note":"Hunting, gathering and fishing did not disappear when farming began. Communities have combined these activities with cultivation, exchange and other work in changing ways. Living Indigenous peoples maintain and renew food and land knowledge; they are contemporary societies, not unchanged examples of a prehistoric stage. This is a thematic overview, not a polity with founding and ending dates.","sources":["regional_deep_past_sapiens","regional_deep_past_livingfoods","regional_deep_past_country","wikipedia_rx-foraging-lifeways"],"collections":["early-world"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Hunter-gatherer","url":"https://en.wikipedia.org/wiki/Hunter-gatherer","pageid":210098}},{"id":"rx-fertile-crescent-farming","title":"Fertile Crescent · early farming","region":"westasia","dates":"c. 9500–7000 BC · selected developments","start":-9500,"end":-7000,"category":"Food & land","location":"Southwest Asia · Levant, Anatolia and the Zagros/Mesopotamian regions","wikiTitle":"Neolithic in the Near East","note":"Cultivation, herding and biological domestication developed gradually, with different regional schedules. Wheat, barley and livestock histories should not be reduced to one invention day. The selected range covers important early transformations, not the full life of farming, and is not a global start date for the Neolithic.","sources":["regional_deep_past_fertile","regional_deep_past_mesopotamia","wikipedia_rx-fertile-crescent-farming"],"collections":["early-world","westasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Neolithic in the Near East","url":"https://en.wikipedia.org/wiki/Neolithic_in_the_Near_East","pageid":79292909}},{"id":"rx-gobekli-tepe","title":"Göbekli Tepe","region":"westasia","dates":"c. 9600–8200 BC · monumental structures","start":-9600,"end":-8200,"category":"Archaeological site","location":"Southeastern Anatolia · present-day Türkiye","wikiTitle":"Göbekli Tepe","note":"Communities built large communal structures with carved T-shaped pillars during the Pre-Pottery Neolithic. Hunter-gatherer societies could organise complex construction and ritual life without an empire. These dates describe the monumental archaeological phase; precise functions and relationships between domestic and communal buildings continue to be researched.","sources":["regional_deep_past_gobekli","wikipedia_rx-gobekli-tepe"],"collections":["early-world","westasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Göbekli Tepe","url":"https://en.wikipedia.org/wiki/G%C3%B6bekli_Tepe","pageid":515395}},{"id":"rx-jericho-neolithic","title":"Jericho · Neolithic settlement","region":"westasia","dates":"c. 9000–7000 BC · selected Neolithic phase","start":-9000,"end":-7000,"category":"Archaeological site","location":"Tell es-Sultan · Jordan Valley, Palestine","wikiTitle":"Tell es-Sultan","note":"By the ninth to eighth millennia BC, a sizeable permanent settlement had communal monuments including a tower and wall. Earlier deposits reach about 10,500 BC, and Bronze Age cities developed later. The displayed dates select the Neolithic settlement and do not give the full lifespan of Jericho or imply one continuously unchanged city-state.","sources":["regional_deep_past_jericho","wikipedia_rx-jericho-neolithic"],"collections":["early-world","westasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Tell es-Sultan","url":"https://en.wikipedia.org/wiki/Tell_es-Sultan","pageid":31275529}},{"id":"rx-catalhoyuk","title":"Çatalhöyük · eastern mound","region":"westasia","dates":"c. 7400–6200 BC","start":-7400,"end":-6200,"category":"Archaeological site","location":"Central Anatolia · present-day Türkiye","wikiTitle":"Çatalhöyük","note":"Densely built houses, burials, wall paintings and symbolic objects reveal a large Neolithic community. This dates the eighteen occupation levels of the eastern mound; the neighbouring western mound has a later history. A substantial settlement need not be presented as a territorial empire.","sources":["regional_deep_past_catalhoyuk","wikipedia_rx-catalhoyuk"],"collections":["early-world","westasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Çatalhöyük","url":"https://en.wikipedia.org/wiki/%C3%87atalh%C3%B6y%C3%BCk","pageid":5765}},{"id":"rx-north-china-millet","title":"Northern China · millet traditions","region":"eastasia","dates":"c. 8000–4500 BC · early developments","start":-8000,"end":-4500,"category":"Food & land","location":"Northern China · Yellow River region and neighbouring areas","wikiTitle":"Cishan culture","note":"Millet exploitation, cultivation and settled farming have different chronologies. Cishan microfossils have been interpreted as evidence around 10,000 years ago, while later sites more clearly document established farming communities. Exact early domestication dates and centres remain debated. The article is one archaeological example, not the entire northern Chinese agricultural tradition.","sources":["regional_deep_past_millet","regional_deep_past_domestication","wikipedia_rx-north-china-millet"],"collections":["early-world","eastasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Cishan culture","url":"https://en.wikipedia.org/wiki/Cishan_culture","pageid":6239188}},{"id":"rx-yangtze-rice","title":"Yangtze valleys · rice cultivation","region":"eastasia","dates":"c. 7000–2300 BC · selected long transition","start":-7000,"end":-2300,"category":"Food & land","location":"Middle and lower Yangtze regions · present-day China","wikiTitle":"Rice domestication","note":"Archaeological rice remains record a prolonged process of cultivation and selection, rather than a finished domesticated crop appearing at one moment. Evidence from lower-Yangtze sites spans roughly 9000–4300 years before present. This selected frame follows that evidence; earlier plant use and other Asian rice histories should not be collapsed into it.","sources":["regional_deep_past_rice","wikipedia_rx-yangtze-rice"],"collections":["early-world","eastasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"History of rice cultivation","url":"https://en.wikipedia.org/wiki/History_of_rice_cultivation","pageid":67244439}},{"id":"rx-mesoamerican-cultivation","title":"Mesoamerica · early crop cultivation","region":"americas","dates":"c. 8000–4000 BC · selected early evidence","start":-8000,"end":-4000,"category":"Food & land","location":"Present-day Mexico and neighbouring Mesoamerica","wikiTitle":"Agriculture in Mesoamerica","note":"Squash domestication and the beginnings of maize cultivation long predated later city-states. Maize developed from teosinte beginning about 9000 years ago in southwestern Mexico; its domestication and spread continued across communities over millennia. These are rounded early-evidence dates, not the moment every community adopted farming or a single beginning for all American agriculture.","sources":["regional_deep_past_maize","regional_deep_past_squash","wikipedia_rx-mesoamerican-cultivation"],"collections":["early-world","americas"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Agriculture in Mesoamerica","url":"https://en.wikipedia.org/wiki/Agriculture_in_Mesoamerica","pageid":336649}},{"id":"rx-andean-horticulture","title":"Andes · early horticulture","region":"americas","dates":"c. 8000–4000 BC · selected early evidence","start":-8000,"end":-4000,"category":"Food & land","location":"Northern Peru · selected Andean valleys","wikiTitle":"History of agriculture","note":"Preceramic sites record developing horticultural economies involving plants such as squash, peanuts and cotton. The evidence places early developments in parts of the Andes around 10,000 years ago. Crops and techniques accumulated at different times; this selected regional record does not make one valley the sole source of all Andean farming.","sources":["regional_deep_past_andes","wikipedia_rx-andean-horticulture"],"collections":["early-world","americas"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"History of agriculture","url":"https://en.wikipedia.org/wiki/History_of_agriculture","pageid":2899597}},{"id":"rx-kuk-agriculture","title":"Kuk · New Guinea agriculture","region":"oceania","dates":"c. 5000 BC–present · changing land use","start":-5000,"end":null,"ongoing":true,"category":"Food & land","location":"Upper Wahgi Valley · Papua New Guinea highlands","wikiTitle":"Kuk Swamp","note":"Wetland mounds demonstrate cultivation around 7000–6400 years ago; later ditch systems and changing land use extend toward the present. Possible earlier plant management reaches about 10,000 years ago, but is not equivalent to unequivocal cultivation. Kuk supports an independent New Guinea agricultural history. Land use was persistent but episodic, not one unchanged system.","sources":["regional_deep_past_kuk","wikipedia_rx-kuk-agriculture"],"collections":["early-world","oceania"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Kuk Swamp","url":"https://en.wikipedia.org/wiki/Kuk_Swamp","pageid":7211274}},{"id":"rx-west-african-cultivation","title":"West Africa · agricultural traditions","region":"africa","dates":"3rd millennium BC onward · varied processes","start":-3000,"end":null,"ongoing":true,"category":"Food & land","location":"Western Sahel and other West African ecological zones","wikiTitle":"History of agriculture","note":"Pearl millet domestication in the western Sahel was one of several African agricultural developments. In northern Mali, early cultivation coexisted with herding, fishing, hunting and gathering. The date selects an early evidence horizon, not the birth of all West African farming. Different crops and environments followed different schedules; cultivated and fully domesticated forms must be distinguished.","sources":["regional_deep_past_pearlmillet","regional_deep_past_africancrops","wikipedia_rx-west-african-cultivation"],"collections":["early-world","africa"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"History of agriculture","url":"https://en.wikipedia.org/wiki/History_of_agriculture","pageid":2899597}},{"id":"rx-mehrgarh-early-farmers","title":"Mehrgarh · aceramic farming community","region":"southasia","dates":"c. 5250–4650 BC · revised Period I","start":-5250,"end":-4650,"category":"Archaeological site","location":"Balochistan · present-day Pakistan","wikiTitle":"Mehrgarh","note":"A 2025 study of tooth enamel from 23 burials proposes a much later date for the aceramic Neolithic phase than the familiar c. 7000 BC chronology. The displayed range rounds its revised model for Period I, not the full settlement history or every farming community in South Asia. The revision concerns archaeological evidence and remains open to further testing.","sources":["regional_deep_past_mehrgarh","regional_deep_past_mehrgarhteam","wikipedia_rx-mehrgarh-early-farmers"],"collections":["early-world","southasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Mehrgarh","url":"https://en.wikipedia.org/wiki/Mehrgarh","pageid":20675}},{"id":"rx-eastern-woodlands-crops","title":"Eastern North America · native crops","region":"americas","dates":"c. 2500–2000 BC · early domestication evidence","start":-2500,"end":-2000,"category":"Food & land","location":"Eastern Woodlands · present-day United States","wikiTitle":"Eastern Agricultural Complex","note":"Communities domesticated native seed crops independently of Mesoamerican maize farming. Archaeological changes document several domesticates by about 4500–4000 years before present, although wild foods remained important and the later shift toward crop dependence was gradual. This dates a selected evidence phase, not the full life of these food systems or the founding of a single people.","sources":["regional_deep_past_domestication","wikipedia_rx-eastern-woodlands-crops"],"collections":["early-world","americas"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Eastern Agricultural Complex","url":"https://en.wikipedia.org/wiki/Eastern_Agricultural_Complex","pageid":3992015}},{"id":"rx-viking","title":"Viking Age · Scandinavian societies","region":"europe","dates":"c. 800–1050 AD","start":800,"end":1050,"category":"period","location":"Scandinavia, North Atlantic and wider exchange routes","note":"An archaeological and historical period, not a single empire or ethnicity. Farming, seafaring, trade, enslavement, migration and warfare connected diverse communities; the rounded museum convention differs from 793–1066 often used in British histories.","wikiTitle":"Viking Age","sources":["regional_europe_viking","wikipedia_rx-viking"],"collections":["europe"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Viking Age","url":"https://en.wikipedia.org/wiki/Viking_Age","pageid":32538}},{"id":"rx-sami","title":"Sámi · continuing Indigenous histories","region":"europe","dates":"Continuing histories · no single founding date","start":null,"end":2027,"category":"culture","location":"Sápmi · northern Norway, Sweden, Finland and Russia’s Kola Peninsula","note":"Diverse Indigenous communities, languages and ways of life continue across state borders. There is no defensible single founding year. Norse expansion or the creation of modern Nordic states did not end Sámi histories or rights; reindeer herding is one of several livelihoods.","wikiTitle":"Sámi","sources":["regional_europe_sami","regional_europe_samilands","wikipedia_rx-sami"],"collections":["europe"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Sámi people","url":"https://en.wikipedia.org/wiki/S%C3%A1mi_people","pageid":27122}},{"id":"rx-norway","title":"Norway · kingdoms, unions and modern state","region":"europe","dates":"c. 900 AD–present · changing political forms","start":900,"end":2027,"category":"period","location":"Norway · Scandinavian peninsula","note":"A broad historical frame, not uninterrupted independent sovereignty. Consolidation of medieval kingship was gradual; c. 900 rounds the late ninth-century tradition. Danish rule and union with Sweden intervened; the latter ended in 1905. The present kingdom’s borders and institutions developed over time.","wikiTitle":"History of Norway","sources":["regional_europe_norway","regional_europe_norway1905","wikipedia_rx-norway"],"collections":["europe"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"History of Norway","url":"https://en.wikipedia.org/wiki/History_of_Norway","pageid":56140}},{"id":"rx-sweden","title":"Sweden · medieval kingdom and modern state","region":"europe","dates":"Middle Ages–present · no single founding year","start":null,"end":2027,"category":"period","location":"Sweden · Scandinavian peninsula","note":"Sweden emerged gradually as a unified medieval kingdom; no precise founding year is implied. The Kalmar Union and the 1523 election of Gustav Vasa were major political changes. A realm’s shifting boundaries should not be confused with the origins of its peoples.","wikiTitle":"History of Sweden","sources":["regional_europe_sweden","regional_europe_sweden1523","wikipedia_rx-sweden"],"collections":["europe"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"History of Sweden","url":"https://en.wikipedia.org/wiki/History_of_Sweden","pageid":39766}},{"id":"rx-denmark","title":"Denmark · kingdom and modern state","region":"europe","dates":"c. 965 AD–present · selected political frame","start":965,"end":2027,"category":"period","location":"Denmark · Scandinavia; wider Danish Realm","note":"A selected political frame anchored around Harald Bluetooth’s conversion and Jelling monument, rather than a founding date for Denmark or Danish people. The Kalmar Union, territorial losses, the 1849 constitution and German occupation in 1940–1945 belong to different political phases; the Danish Realm extends beyond European Denmark.","wikiTitle":"History of Denmark","sources":["regional_europe_denmark","regional_europe_viking","wikipedia_rx-denmark"],"collections":["europe"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"History of Denmark","url":"https://en.wikipedia.org/wiki/History_of_Denmark","pageid":54327}},{"id":"rx-iceland","title":"Iceland · Commonwealth, unions and republic","region":"europe","dates":"930 AD–present · changing political forms","start":930,"end":2027,"category":"period","location":"Iceland · North Atlantic","note":"930 marks the establishment of the Althing, not first human settlement. The Commonwealth came under Norway in 1262–1264 and later Danish rule; sovereignty in 1918 retained a common monarch, and the republic was established in 1944. These were different constitutional arrangements.","wikiTitle":"History of Iceland","sources":["regional_europe_iceland","wikipedia_rx-iceland"],"collections":["europe"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"History of Iceland","url":"https://en.wikipedia.org/wiki/History_of_Iceland","pageid":64578}},{"id":"rx-finland","title":"Finland · independent state","region":"europe","dates":"1917 AD–present","start":1917,"end":2027,"category":"history","location":"Finland · northern Europe","note":"Parliament approved independence on 6 December 1917; the republic’s constitution followed in 1919. This dates the selected independent state, not Finnish or Sámi origins. Earlier Swedish rule and the autonomous Grand Duchy under Russia preceded independence.","wikiTitle":"Finland","sources":["regional_europe_finland","wikipedia_rx-finland"],"collections":["europe"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Finland","url":"https://en.wikipedia.org/wiki/Finland","pageid":10577}},{"id":"rx-polish-lithuanian","title":"Polish–Lithuanian Commonwealth","region":"europe","dates":"1569–1795 AD","start":1569,"end":1795,"category":"history","location":"Central and eastern Europe · changing multiethnic territories","note":"The Union of Lublin joined the Kingdom of Poland and Grand Duchy of Lithuania in a common political framework. Earlier unions preceded 1569. The partitions ended the Commonwealth in 1795; its diverse populations and their histories continued.","wikiTitle":"Polish–Lithuanian Commonwealth","sources":["regional_europe_commonwealth","wikipedia_rx-polish-lithuanian"],"collections":["europe"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Polish–Lithuanian Commonwealth","url":"https://en.wikipedia.org/wiki/Polish%E2%80%93Lithuanian_Commonwealth","pageid":343234}},{"id":"rx-poland","title":"Poland · restored state and modern eras","region":"europe","dates":"1918 AD–present · changing borders and regimes","start":1918,"end":2027,"category":"period","location":"Poland · central Europe","note":"1918 marks restoration after the partitions, not the beginning of Polish history. Nazi German and Soviet invasion and occupation from 1939, a government in exile, postwar border changes, communist government and the transition after 1989 interrupt any simple story of continuous sovereign rule.","wikiTitle":"Poland","sources":["regional_europe_poland","regional_europe_polandmodern","wikipedia_rx-poland"],"collections":["europe"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Poland","url":"https://en.wikipedia.org/wiki/Poland","pageid":22936}},{"id":"rx-hungary-kingdom","title":"Kingdom of Hungary · changing royal realms","region":"europe","dates":"c. 1000–1918 AD","start":1000,"end":1918,"category":"period","location":"Carpathian Basin · central Europe","note":"Stephen’s coronation is conventionally dated 1000 or 1001. This umbrella covers major territorial division after 1526, Ottoman rule in central areas, Habsburg royal government and the 1867 dual monarchy; it is not one unchanged or continuously independent territory. Later restoration of the kingdom in 1920–1946 is outside this selected frame.","wikiTitle":"Kingdom of Hungary","sources":["regional_europe_hungary","regional_europe_hungarystart","wikipedia_rx-hungary-kingdom"],"collections":["europe"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Kingdom of Hungary","url":"https://en.wikipedia.org/wiki/Kingdom_of_Hungary","pageid":879716}},{"id":"rx-hungary","title":"Hungary · post-Habsburg and modern eras","region":"europe","dates":"1918 AD–present · changing regimes","start":1918,"end":2027,"category":"period","location":"Hungary · central Europe","note":"The Habsburg monarchy’s collapse in 1918 begins this selected modern frame. Republics, the 1920–1946 kingdom, wartime occupation, communist rule and the democratic transition after 1989 are distinct phases. Hungarian history and communities predate 1918 and extend beyond modern borders.","wikiTitle":"History of Hungary","sources":["regional_europe_hungary","wikipedia_rx-hungary"],"collections":["europe"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"History of Hungary","url":"https://en.wikipedia.org/wiki/History_of_Hungary","pageid":27598309}},{"id":"rx-medieval-ireland","title":"Ireland · later medieval societies","region":"europe","dates":"c. 1150–1550 AD","start":1150,"end":1550,"category":"period","location":"Island of Ireland","note":"Uses the National Museum’s later-medieval convention, from church reform to the Reformation. Gaelic lordships, Anglo-Norman settlements, towns, religious communities and changing English claims overlapped. This is not a single unified Irish state, nor does 1550 mark the end of Gaelic culture.","wikiTitle":"History of Ireland (1169–1536)","sources":["regional_europe_ireland","wikipedia_rx-medieval-ireland"],"collections":["europe"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"History of Ireland (1169–1534)","url":"https://en.wikipedia.org/wiki/History_of_Ireland_(1169%E2%80%931534)","pageid":3031324}},{"id":"rx-dutch-republic","title":"Dutch Republic · United Provinces","region":"europe","dates":"1588–1795 AD","start":1588,"end":1795,"category":"history","location":"Northern Low Countries · northwestern Europe","note":"1588 conventionally marks the republican form after earlier revolt, the Union of Utrecht in 1579 and the Act of Abjuration in 1581. Recognition of independence followed in 1648. French invasion and the Batavian Revolution ended this republic in 1795; the modern kingdom began later.","wikiTitle":"Dutch Republic","sources":["regional_europe_dutch","regional_europe_dutchdates","regional_europe_dutch1648","wikipedia_rx-dutch-republic"],"collections":["europe"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Dutch Republic","url":"https://en.wikipedia.org/wiki/Dutch_Republic","pageid":52626}},{"id":"rx-netherlands","title":"Netherlands · kingdom and modern state","region":"europe","dates":"1815 AD–present","start":1815,"end":2027,"category":"history","location":"Northwestern Europe and the Kingdom’s Caribbean territories","note":"The kingdom proclaimed in 1815 initially included the southern provinces; Belgium separated in 1830 and was recognised in 1839. The present Kingdom comprises the Netherlands, Aruba, Curaçao and Sint Maarten. It is not identical to the earlier Dutch Republic or an unchanged colonial empire.","wikiTitle":"Kingdom of the Netherlands","sources":["regional_europe_netherlands","wikipedia_rx-netherlands"],"collections":["europe"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Kingdom of the Netherlands","url":"https://en.wikipedia.org/wiki/Kingdom_of_the_Netherlands","pageid":18949613}},{"id":"rx-bulgaria-medieval","title":"Medieval Bulgarian states · first and second empires","region":"europe","dates":"681–1396 AD · interrupted political frame","start":681,"end":1396,"category":"period","location":"Balkans · shifting territories around present-day Bulgaria","note":"Groups the First Bulgarian Empire (681–1018) and Second (1185/1186–late fourteenth century), separated by Byzantine rule. 1396 is a conventional endpoint for Ottoman conquest; regional remnants and claims complicate an exact final date. It is not one uninterrupted empire.","wikiTitle":"First Bulgarian Empire","sources":["regional_europe_bulgaria","wikipedia_rx-bulgaria-medieval"],"collections":["europe"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"First Bulgarian Empire","url":"https://en.wikipedia.org/wiki/First_Bulgarian_Empire","pageid":2843775}},{"id":"rx-bulgaria","title":"Bulgaria · principality, kingdom and republic","region":"europe","dates":"1878 AD–present","start":1878,"end":2027,"category":"period","location":"Bulgaria · southeastern Europe","note":"The autonomous principality established in 1878 remained formally under Ottoman suzerainty until independence in 1908. The monarchy, communist republic and post-1989 parliamentary republic are separate phases; 1878 is not an origin date for Bulgarian people.","wikiTitle":"History of Bulgaria","sources":["regional_europe_bulgaria","regional_europe_bulgaria1908","wikipedia_rx-bulgaria"],"collections":["europe"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"History of Bulgaria","url":"https://en.wikipedia.org/wiki/History_of_Bulgaria","pageid":42542}},{"id":"rx-serbia-medieval","title":"Medieval Serbian realms","region":"europe","dates":"1217–1459 AD · selected royal and successor phases","start":1217,"end":1459,"category":"period","location":"Central and western Balkans","note":"1217 marks Stefan’s royal coronation, after earlier Serbian principalities. Kingdom, empire and successor despotate are grouped here; their borders and degree of control changed. The Ottoman capture of Smederevo in 1459 ends this selected frame, not Serbian society.","wikiTitle":"History of Serbia in the Middle Ages","sources":["regional_europe_serbiamedieval","regional_europe_serbia1459","wikipedia_rx-serbia-medieval"],"collections":["europe"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Serbia in the Middle Ages","url":"https://en.wikipedia.org/wiki/Serbia_in_the_Middle_Ages","pageid":2843257}},{"id":"rx-serbia","title":"Serbia · independent republic after state union","region":"europe","dates":"2006 AD–present","start":2006,"end":2027,"category":"history","location":"Serbia · southeastern Europe","note":"2006 marks the end of the state union with Montenegro, not the first Serbian state or independence. Serbia continued the union’s UN membership. Kosovo declared independence in 2008; its international status remains contested, and this listing does not resolve that dispute.","wikiTitle":"Serbia","sources":["regional_europe_yugoslavsuccessors","regional_europe_yugoslavchange","regional_europe_kosovodeclaration","regional_europe_kosovomandate","wikipedia_rx-serbia"],"collections":["europe"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Serbia","url":"https://en.wikipedia.org/wiki/Serbia","pageid":29265}},{"id":"rx-croatia-medieval","title":"Medieval Kingdom of Croatia · selected phase","region":"europe","dates":"c. 925–1102 AD","start":925,"end":1102,"category":"history","location":"Eastern Adriatic and neighbouring inland regions","note":"925 is the traditional royal convention associated with Tomislav; 1102 conventionally marks rule under the Hungarian crown. Details of the union and the later Pacta conventa text require caution. The range does not imply Croatia or Croatian institutions disappeared in 1102.","wikiTitle":"Kingdom of Croatia (925–1102)","sources":["regional_europe_croatiamedieval","wikipedia_rx-croatia-medieval"],"collections":["europe"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Kingdom of Croatia (925–1102)","url":"https://en.wikipedia.org/wiki/Kingdom_of_Croatia_(925%E2%80%931102)","pageid":2582233}},{"id":"rx-croatia","title":"Croatia · independent republic","region":"europe","dates":"1991 AD–present","start":1991,"end":2027,"category":"history","location":"Croatia · eastern Adriatic and southeastern Europe","note":"1991 dates declarations and implementation of independence from Yugoslavia, followed by war and later international recognition. Croatia joined the UN in 1992. This is a modern state convention, not the beginning of Croatian communities or institutions.","wikiTitle":"Croatia","sources":["regional_europe_croatia","regional_europe_yugoslavsuccessors","wikipedia_rx-croatia"],"collections":["europe"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Croatia","url":"https://en.wikipedia.org/wiki/Croatia","pageid":5573}},{"id":"rx-bosnia-medieval","title":"Medieval Bosnia · bans and kings","region":"europe","dates":"c. 950–1463 AD · selected regional frame","start":950,"end":1463,"category":"period","location":"Bosnia and neighbouring western Balkan territories","note":"A rounded frame following the National Museum’s mid-tenth-century emergence of the medieval Bosnian state through changing bans and royal rule. The Ottoman conquest in 1463 ends this selected state frame; local communities, religious traditions and regional institutions continued.","wikiTitle":"History of Bosnia and Herzegovina in the Middle Ages","sources":["regional_europe_bosniamedieval","wikipedia_rx-bosnia-medieval"],"collections":["europe"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Bosnia and Herzegovina in the Middle Ages","url":"https://en.wikipedia.org/wiki/Bosnia_and_Herzegovina_in_the_Middle_Ages","pageid":4241541}},{"id":"rx-bosnia","title":"Bosnia and Herzegovina · independent state","region":"europe","dates":"1992 AD–present","start":1992,"end":2027,"category":"history","location":"Bosnia and Herzegovina · western Balkans","note":"Independence and international recognition came in 1992 during Yugoslavia’s dissolution. War followed; the Dayton agreement in 1995 established the present constitutional framework. Bosnia and Herzegovina is one sovereign state with internal entities, not two independent countries.","wikiTitle":"Bosnia and Herzegovina","sources":["regional_europe_bosnia","regional_europe_dayton","wikipedia_rx-bosnia"],"collections":["europe"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Bosnia and Herzegovina","url":"https://en.wikipedia.org/wiki/Bosnia_and_Herzegovina","pageid":3463}},{"id":"rx-yugoslav-states","title":"Yugoslav states · monarchy and changing federations","region":"europe","dates":"1918–2006 AD · changing and overlapping forms","start":1918,"end":2006,"category":"period","location":"Western Balkans · territories changed markedly","note":"The 1918 kingdom, wartime occupation and resistance, socialist federation, and 1992–2003 Federal Republic of Yugoslavia were different arrangements. The last became Serbia and Montenegro in 2003 and ended in 2006. The 1992 federation was not automatically accepted as the sole continuation of socialist Yugoslavia.","wikiTitle":"Yugoslavia","sources":["regional_europe_yugoslavia","regional_europe_yugoslavchange","wikipedia_rx-yugoslav-states"],"collections":["europe"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Yugoslavia","url":"https://en.wikipedia.org/wiki/Yugoslavia","pageid":34244}},{"id":"rx-slovenia","title":"Slovenia · independent republic","region":"europe","dates":"1991 AD–present","start":1991,"end":2027,"category":"history","location":"Slovenia · Alpine–Adriatic region","note":"The assembly adopted independence acts on 25 June 1991, followed by declaration and a short war. UN admission followed in 1992. This dates the selected sovereign state, not the origins of Slovene communities or the entire history of the territory.","wikiTitle":"Slovenia","sources":["regional_europe_slovenia","regional_europe_yugoslavsuccessors","wikipedia_rx-slovenia"],"collections":["europe"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Slovenia","url":"https://en.wikipedia.org/wiki/Slovenia","pageid":27338}},{"id":"rx-montenegro","title":"Montenegro · restored independence","region":"europe","dates":"2006 AD–present","start":2006,"end":2027,"category":"history","location":"Montenegro · western Balkans and Adriatic","note":"The referendum of 21 May was followed by parliament’s declaration on 3 June 2006, ending union with Serbia. Earlier Montenegrin statehood preceded Yugoslavia, so 2006 is restoration in a new constitutional setting rather than the beginning of Montenegrin history.","wikiTitle":"Montenegro","sources":["regional_europe_montenegro","regional_europe_yugoslavsuccessors","wikipedia_rx-montenegro"],"collections":["europe"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Montenegro","url":"https://en.wikipedia.org/wiki/Montenegro","pageid":20760}},{"id":"rx-north-macedonia","title":"North Macedonia · independent state","region":"europe","dates":"1991 AD–present","start":1991,"end":2027,"category":"history","location":"North Macedonia · southeastern Europe","note":"The September 1991 referendum begins this selected independence frame. The state entered the UN in 1993 under a provisional designation; the country’s name changed to North Macedonia in 2019 after the Prespa agreement. Modern statehood is not a claim that one ancient polity survived unchanged.","wikiTitle":"North Macedonia","sources":["regional_europe_northmacedonia","regional_europe_yugoslavsuccessors","regional_europe_northmacedonia2019","wikipedia_rx-north-macedonia"],"collections":["europe"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"North Macedonia","url":"https://en.wikipedia.org/wiki/North_Macedonia","pageid":23564616}},{"id":"rx-pyu","title":"Pyu · urban communities","region":"eastasia","dates":"c. 2nd century BC–9th century AD","start":-200,"end":900,"category":"culture","location":"Ayeyarwady dry zone · Myanmar","note":"Halin, Beikthano and Sri Ksetra preserve a long sequence of walled settlements, water management, Buddhist institutions and exchange. This is an archaeological urban tradition, not evidence for one empire with fixed borders. Rounded century limits describe the documented sequence.","wikiTitle":"Pyu city-states","sources":["regional_southeast_pyu","wikipedia_rx-pyu"],"collections":["southeastasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Pyu city-states","url":"https://en.wikipedia.org/wiki/Pyu_city-states","pageid":2596525}},{"id":"rx-bagan","title":"Bagan · imperial and temple-building phase","region":"eastasia","dates":"c. 11th–13th centuries AD","start":1000,"end":1300,"category":"history","location":"Ayeyarwady Valley · Myanmar","note":"The Bagan landscape records a major Buddhist capital and regional empire. The range marks its best-known monumental and imperial phase, not the full occupation of the city or the beginning of Burmese history.","wikiTitle":"Bagan","sources":["regional_southeast_bagan","wikipedia_rx-bagan"],"collections":["southeastasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Bagan","url":"https://en.wikipedia.org/wiki/Bagan","pageid":222414}},{"id":"rx-toungoo","title":"Toungoo · expanding and restored courts","region":"eastasia","dates":"c. 1486–1752 AD","start":1486,"end":1752,"category":"history","location":"Myanmar and changing areas of mainland Southeast Asia","note":"A dynastic umbrella for an initially local court, sixteenth-century imperial expansion and a smaller restored kingdom. The late-sixteenth-century collapse and subsequent restoration interrupt any simple picture of continuous territorial control. Shan, Mon and neighbouring powers retained distinct histories.","wikiTitle":"Toungoo dynasty","sources":["regional_southeast_ceramics","wikipedia_rx-toungoo"],"collections":["southeastasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Toungoo dynasty","url":"https://en.wikipedia.org/wiki/Toungoo_dynasty","pageid":8558752}},{"id":"rx-konbaung","title":"Konbaung dynasty","region":"eastasia","dates":"1752–1885 AD","start":1752,"end":1885,"category":"history","location":"Myanmar and changing borderlands","note":"Konbaung kings expanded their realm and later lost territory in successive wars with British forces. British capture of Mandalay and exile of King Thibaw in 1885 ended the dynasty; formal annexation of Upper Burma followed in 1886.","wikiTitle":"Konbaung dynasty","sources":["regional_southeast_burma","wikipedia_rx-konbaung"],"collections":["southeastasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Konbaung dynasty","url":"https://en.wikipedia.org/wiki/Konbaung_dynasty","pageid":1439423}},{"id":"rx-burma-colonial","title":"Burma · British expansion and colonial rule","region":"eastasia","dates":"1826–1948 AD · interrupted 1942–1945","start":1826,"end":1948,"category":"period","location":"Present-day Myanmar · changing colonial territories","note":"British rule spread in stages after the wars of 1824–1826, 1852–1853 and 1885. These dates do not imply the whole present-day country was colonised in 1826. Japanese occupation interrupted British control during the Second World War; independence followed in January 1948.","wikiTitle":"British rule in Burma","sources":["regional_southeast_burma","wikipedia_rx-burma-colonial"],"collections":["southeastasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"British rule in Burma","url":"https://en.wikipedia.org/wiki/British_rule_in_Burma","pageid":3985183}},{"id":"rx-myanmar","title":"Myanmar / Burma · independent state","region":"eastasia","dates":"1948–present","start":1948,"end":2027,"category":"history","location":"Mainland Southeast Asia","note":"Independence on 4 January 1948 anchors this modern-state entry. Its broad span includes major changes in government and continuing conflicts; it does not imply an unchanged constitution, uniform central control or the disappearance of the country’s many peoples.","wikiTitle":"Myanmar","sources":["regional_southeast_burmaind","wikipedia_rx-myanmar"],"collections":["southeastasia"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Myanmar","url":"https://en.wikipedia.org/wiki/Myanmar","pageid":19457}},{"id":"rx-dvaravati","title":"Dvaravati · towns and cultural networks","region":"eastasia","dates":"c. 6th–11th centuries AD","start":500,"end":1100,"category":"culture","location":"Central and northeastern present-day Thailand and adjoining areas","note":"Buddhist monuments, inscriptions and material culture link several early urban centres. Dvaravati is treated here as a cultural and political network rather than one securely bounded empire. Individual sites and traditions flourished at different times within this approximate range.","wikiTitle":"Dvaravati","sources":["regional_southeast_dvaravati","regional_southeast_dvaravati_study","wikipedia_rx-dvaravati"],"collections":["southeastasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Dvaravati","url":"https://en.wikipedia.org/wiki/Dvaravati","pageid":523314}},{"id":"rx-sukhothai","title":"Sukhothai kingdom","region":"eastasia","dates":"c. 1238–1438 AD","start":1238,"end":1438,"category":"history","location":"North-central present-day Thailand","note":"An important court and group of towns supported Buddhist architecture and ceramics. The conventional kingdom range includes later dependence on Ayutthaya before annexation; it is not a claim that all of present-day Thailand was unified under Sukhothai.","wikiTitle":"Sukhothai Kingdom","sources":["regional_southeast_sukhothai","regional_southeast_thaiheritage","wikipedia_rx-sukhothai"],"collections":["southeastasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Sukhothai Kingdom","url":"https://en.wikipedia.org/wiki/Sukhothai_Kingdom","pageid":174668}},{"id":"rx-ayutthaya","title":"Ayutthaya kingdom","region":"eastasia","dates":"1350/1351–1767 AD","start":1350,"end":1767,"category":"history","location":"Chao Phraya basin and changing tributary networks","note":"Ayutthaya became a major diplomatic and commercial capital. Sources use 1350 or 1351 for its founding. Its reach changed over time; the Burmese destruction of the capital in 1767 ended this ruling phase, not Siamese society.","wikiTitle":"Ayutthaya Kingdom","sources":["regional_southeast_ayutthaya","regional_southeast_thaithonburi","wikipedia_rx-ayutthaya"],"collections":["southeastasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Ayutthaya Kingdom","url":"https://en.wikipedia.org/wiki/Ayutthaya_Kingdom","pageid":165348}},{"id":"rx-thonburi","title":"Thonburi kingdom","region":"eastasia","dates":"1767–1782 AD","start":1767,"end":1782,"category":"history","location":"Chao Phraya basin · present-day Thailand","note":"King Taksin established a court at Thonburi after Ayutthaya’s fall and reconsolidated power amid competing regional centres. Bangkok became the new royal capital under Rama I in 1782.","wikiTitle":"Thonburi Kingdom","sources":["regional_southeast_thaithonburi","wikipedia_rx-thonburi"],"collections":["southeastasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Thonburi Kingdom","url":"https://en.wikipedia.org/wiki/Thonburi_Kingdom","pageid":4557934}},{"id":"rx-siam-thailand","title":"Siam / Thailand · Bangkok and constitutional eras","region":"eastasia","dates":"1782–present","start":1782,"end":2027,"category":"history","location":"Mainland Southeast Asia · present-day Thailand","note":"The Bangkok era began in 1782. Absolute monarchy ended in 1932, followed by successive constitutional and military governments. The name Thailand was adopted in 1939, with a later temporary return to Siam; neither the name change nor 1782 marks the beginning of the region’s peoples.","wikiTitle":"History of Thailand","sources":["regional_southeast_thaidiplomacy","regional_southeast_thaiconstitution","regional_southeast_names","wikipedia_rx-siam-thailand"],"collections":["southeastasia"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"History of Thailand","url":"https://en.wikipedia.org/wiki/History_of_Thailand","pageid":30129}},{"id":"rx-champa","title":"Champa · changing Cham polities","region":"eastasia","dates":"c. 2nd century–1832 AD","start":192,"end":1832,"category":"history","location":"Coastal central and southern present-day Vietnam","note":"Champa comprised changing regional centres and principalities rather than an unchanging nation-state. My Son preserves major religious monuments; southern Panduranga outlasted the fall of Vijaya in 1471 and was absorbed by the Nguyễn state in 1832. Cham people and cultural traditions continue.","wikiTitle":"Champa","sources":["regional_southeast_myson","regional_southeast_ceramics","wikipedia_rx-champa"],"collections":["southeastasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Champa","url":"https://en.wikipedia.org/wiki/Champa","pageid":153039}},{"id":"rx-cham-communities","title":"Chăm communities · living histories","region":"eastasia","dates":"Historical roots–present","start":null,"end":2027,"category":"culture","location":"Vietnam, Cambodia and wider communities","note":"Cham history continues beyond the loss of independent principalities. Living pottery traditions in Vietnam, passed on within families and communities, offer one documented example. This entry does not assign a single founding date to a diverse people or reduce Cham life to a former kingdom.","wikiTitle":"Chams","sources":["regional_southeast_cham","wikipedia_rx-cham-communities"],"collections":["southeastasia"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Chams","url":"https://en.wikipedia.org/wiki/Chams","pageid":153025}},{"id":"rx-butuan-boats","title":"Butuan · maritime communities and boat-building","region":"eastasia","dates":"c. 8th–10th centuries AD · boat evidence","start":700,"end":1000,"category":"culture","location":"Northeastern Mindanao · Philippines","note":"Excavated lashed-lug boats attest to sophisticated boat-building and maritime connections. This selected range dates the boat evidence identified by the National Museum, not the fixed lifespan or borders of a supposed kingdom. Settlement and trade at Butuan extended beyond it.","wikiTitle":"Balangay","sources":["regional_southeast_butuan","wikipedia_rx-butuan-boats"],"collections":["southeastasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Balangay","url":"https://en.wikipedia.org/wiki/Balangay","pageid":24467136}},{"id":"rx-sulu","title":"Sulu sultanate · political authority","region":"eastasia","dates":"c. 1450–1915 AD","start":1450,"end":1915,"category":"history","location":"Sulu Archipelago and changing maritime networks","note":"A Muslim sultanate developed within older island trading societies. Its autonomy contracted under Spanish and American expansion; the 1915 agreement ended the sultan’s temporal sovereignty. Religious authority, communities and contested later claims have separate histories, and 1915 does not mark their disappearance.","wikiTitle":"Sultanate of Sulu","sources":["regional_southeast_sulu","wikipedia_rx-sulu"],"collections":["southeastasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Sultanate of Sulu","url":"https://en.wikipedia.org/wiki/Sultanate_of_Sulu","pageid":690763}},{"id":"rx-philippines-spanish","title":"Philippines · Spanish colonial rule","region":"eastasia","dates":"1565–1898 AD","start":1565,"end":1898,"category":"period","location":"Philippine archipelago · uneven colonial reach","note":"Permanent Spanish settlement began in 1565; colonial rule expanded unevenly and faced continuing Indigenous and Muslim resistance. The revolution and the 1898 transfer claimed by Spain and the United States did not amount to a consensual transfer of every community’s sovereignty.","wikiTitle":"History of the Philippines (1565–1898)","sources":["regional_southeast_spanishphil","regional_southeast_philcolonial","wikipedia_rx-philippines-spanish"],"collections":["southeastasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"History of the Philippines (1565–1898)","url":"https://en.wikipedia.org/wiki/History_of_the_Philippines_(1565%E2%80%931898)","pageid":23888361}},{"id":"rx-philippines-us","title":"Philippines · revolution, U.S. rule and war","region":"eastasia","dates":"1898–1946 AD · Japanese occupation 1942–1945","start":1898,"end":1946,"category":"period","location":"Philippine archipelago","note":"Filipino revolutionaries asserted independence and founded the First Republic while the United States imposed colonial rule. The Commonwealth began in 1935; Japanese invasion and occupation interrupted American administration. The United States formally recognised Philippine independence on 4 July 1946.","wikiTitle":"History of the Philippines (1898–1946)","sources":["regional_southeast_philcolonial","regional_southeast_philind","wikipedia_rx-philippines-us"],"collections":["southeastasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"History of the Philippines (1898–1946)","url":"https://en.wikipedia.org/wiki/History_of_the_Philippines_(1898%E2%80%931946)","pageid":5807102}},{"id":"rx-philippines","title":"Philippines · independent republic","region":"eastasia","dates":"1946–present","start":1946,"end":2027,"category":"history","location":"Island Southeast Asia","note":"The 1946 date marks internationally recognised independence after American colonial rule. The earlier 1898 declaration remains commemorated as Independence Day. A single modern-state entry cannot stand for every Indigenous nation, regional community or constitutional era within the archipelago.","wikiTitle":"Philippines","sources":["regional_southeast_philind","regional_southeast_philcolonial","wikipedia_rx-philippines"],"collections":["southeastasia"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Philippines","url":"https://en.wikipedia.org/wiki/Philippines","pageid":23440}},{"id":"rx-melaka","title":"Melaka · Malay sultanate and trading port","region":"eastasia","dates":"c. 1400–1511 AD · sultanate phase","start":1400,"end":1511,"category":"history","location":"Straits of Malacca · present-day Malaysia","note":"A Malay sultanate made Melaka an important multicultural trading port. Portuguese conquest in 1511 ended this selected ruling phase; the city and regional Malay courts continued under changing conditions. This is not a continuous empire connecting Srivijaya directly to Malaysia.","wikiTitle":"Malacca Sultanate","sources":["regional_southeast_melaka","regional_southeast_malaysia","wikipedia_rx-melaka"],"collections":["southeastasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Malacca Sultanate","url":"https://en.wikipedia.org/wiki/Malacca_Sultanate","pageid":162963}},{"id":"rx-malaysia","title":"Malaysia · federation","region":"eastasia","dates":"1963–present","start":1963,"end":2027,"category":"history","location":"Malay Peninsula and northern Borneo","note":"Malaysia was formed on 16 September 1963 from Malaya, Sabah, Sarawak and Singapore. Malaya had gained independence in 1957; Singapore separated in 1965. The federation’s formation does not date the beginnings of its many Indigenous, Malay, Chinese, Indian and other communities.","wikiTitle":"Malaysia","sources":["regional_southeast_malaysia","regional_southeast_singapore","wikipedia_rx-malaysia"],"collections":["southeastasia"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Malaysia","url":"https://en.wikipedia.org/wiki/Malaysia","pageid":3607937}},{"id":"rx-singapore","title":"Singapore · independent republic","region":"eastasia","dates":"1965–present","start":1965,"end":2027,"category":"history","location":"Southern Straits of Malacca","note":"Singapore became a sovereign republic on 9 August 1965 after separation from Malaysia. Earlier Temasek, Malay and regional histories, the British settlement from 1819, wartime occupation and self-government preceded this modern-state phase.","wikiTitle":"Singapore","sources":["regional_southeast_singapore","wikipedia_rx-singapore"],"collections":["southeastasia"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Singapore","url":"https://en.wikipedia.org/wiki/Singapore","pageid":27318}},{"id":"rx-brunei","title":"Brunei Darussalam · full independence","region":"eastasia","dates":"1984–present","start":1984,"end":2027,"category":"history","location":"Northern Borneo","note":"Full independence resumed on 1 January 1984, ending British responsibility for external affairs and defence. This date identifies the contemporary sovereign-state phase, not the origin of the much older Brunei sultanate or its people.","wikiTitle":"Brunei","sources":["regional_southeast_brunei","wikipedia_rx-brunei"],"collections":["southeastasia"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Brunei","url":"https://en.wikipedia.org/wiki/Brunei","pageid":3466}},{"id":"rx-lanxang","title":"Lan Xang kingdom","region":"eastasia","dates":"1353–1707 AD · conventional range","start":1353,"end":1707,"category":"history","location":"Mekong region · mainly present-day Laos and adjoining areas","note":"Lan Xang developed around interconnected courts and Buddhist centres, including Luang Prabang and later Vientiane. Internal divisions and external pressures changed royal power; partition produced distinct successor kingdoms. Its territory and communities do not map directly onto modern national borders.","wikiTitle":"Lan Xang","sources":["regional_southeast_laochronology","regional_southeast_laocountry","regional_southeast_lanxang","wikipedia_rx-lanxang"],"collections":["southeastasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Lan Xang","url":"https://en.wikipedia.org/wiki/Lan_Xang","pageid":203665}},{"id":"rx-laos","title":"Laos · independence and republic","region":"eastasia","dates":"1953–present","start":1953,"end":2027,"category":"history","location":"Mainland Southeast Asia","note":"The 1953 treaty removed the remaining French restrictions on independence, following earlier autonomy within the French Union. Civil war and extensive bombing shaped later decades. The monarchy ended with proclamation of the Lao People’s Democratic Republic in 1975.","wikiTitle":"Laos","sources":["regional_southeast_laocountry","regional_southeast_laos","wikipedia_rx-laos"],"collections":["southeastasia"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Laos","url":"https://en.wikipedia.org/wiki/Laos","pageid":17752}},{"id":"rx-timor-leste","title":"Timor-Leste · restored independence","region":"eastasia","dates":"2002–present","start":2002,"end":2027,"category":"history","location":"Eastern Timor, Oecusse and neighbouring islands","note":"Independence was declared in 1975, followed by Indonesian invasion and occupation. The 1999 referendum led to a United Nations-administered transition and restoration of independence on 20 May 2002. This modern-state date does not begin Timorese history.","wikiTitle":"Timor-Leste","sources":["regional_southeast_timor","wikipedia_rx-timor-leste"],"collections":["southeastasia"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Timor-Leste","url":"https://en.wikipedia.org/wiki/Timor-Leste","pageid":19159399}},{"id":"rx-karen-communities","title":"Karen communities · living heritage","region":"eastasia","dates":"Historical roots–present","start":null,"end":2027,"category":"culture","location":"Myanmar, Thailand and diaspora communities","note":"Karen is an umbrella for diverse communities rather than one state or uniform identity. Weaving, language, ecological knowledge and community institutions continue across borders and displacement. The selected sources document people sustaining these traditions today; no single origin date is assigned.","wikiTitle":"Karen peoples","sources":["regional_southeast_karen","regional_southeast_karenheritage","wikipedia_rx-karen-communities"],"collections":["southeastasia"],"ongoing":true,"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Karen peoples","url":"https://en.wikipedia.org/wiki/Karen_peoples","pageid":615208}},{"id":"rx-scythian","title":"Scythian and related steppe traditions","region":"centralasia","dates":"c. 900–200 BC","start":-900,"end":-200,"category":"culture","location":"Eurasian steppe · Black Sea to Siberia and Central Asia","note":"A broad archaeological frame for varied mobile communities, regional cultures and ruling groups. Shared horse-riding and artistic traditions do not imply one united empire or a single ancestry for later peoples. The dates are approximate.","wikiTitle":"Scythians","sources":["regional_steppe_arabia_scythian_bm","wikipedia_rx-scythian"],"collections":["centralasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Scythians","url":"https://en.wikipedia.org/wiki/Scythians","pageid":55092}},{"id":"rx-xiongnu","title":"Xiongnu confederation","region":"centralasia","dates":"c. 209 BC–93 AD · selected imperial frame","start":-209,"end":93,"category":"history","location":"Mongolian plateau and neighbouring Inner Asia","note":"An empire brought diverse communities into far-reaching political and exchange networks. The conventional 93 AD endpoint concerns the northern imperial formation; southern Xiongnu governments and communities continued. This is not an ethnic extinction date.","wikiTitle":"Xiongnu","sources":["regional_steppe_arabia_xiongnu_research","regional_steppe_arabia_xiongnu_getty","wikipedia_rx-xiongnu"],"collections":["centralasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Xiongnu","url":"https://en.wikipedia.org/wiki/Xiongnu","pageid":74297}},{"id":"rx-first-turkic","title":"First Turkic Khaganate · early imperial phase","region":"centralasia","dates":"552–c. 603 AD · selected phase","start":552,"end":603,"category":"history","location":"Mongolian plateau and Central Asian steppe","note":"Founded under Bumin, this imperial formation soon developed eastern and western centres. Civil conflict and separation unfolded over decades from the late sixth century; c. 603 is a conventional division marker, not an instantaneous split of a uniformly governed territory.","wikiTitle":"First Turkic Khaganate","sources":["regional_steppe_arabia_turk_unesco","regional_steppe_arabia_turk_washington","regional_steppe_arabia_turk_phd","wikipedia_rx-first-turkic"],"collections":["centralasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"First Turkic Khaganate","url":"https://en.wikipedia.org/wiki/First_Turkic_Khaganate","pageid":14759503}},{"id":"rx-eastern-turkic","title":"Eastern Turkic Khaganate · independent phase","region":"centralasia","dates":"c. 603–630 AD · selected phase","start":603,"end":630,"category":"history","location":"Mongolian plateau and adjacent Inner Asia","note":"Selected post-division phase of eastern Türk rule, ending with Tang military defeat in 630. Earlier eastern government, subsequent Tang arrangements and later restored Türk rule are separate frames; these dates do not delimit all Turkic communities.","wikiTitle":"Eastern Turkic Khaganate","sources":["regional_steppe_arabia_turk_unesco","regional_steppe_arabia_turk_washington","regional_steppe_arabia_turk_phd","wikipedia_rx-eastern-turkic"],"collections":["centralasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Eastern Turkic Khaganate","url":"https://en.wikipedia.org/wiki/Eastern_Turkic_Khaganate","pageid":11436391}},{"id":"rx-western-turkic","title":"Western Turkic Khaganate · independent phase","region":"centralasia","dates":"c. 603–657 AD · selected phase","start":603,"end":657,"category":"history","location":"Central Asia · Semirechye and neighbouring territories","note":"The western ruling centre connected steppe alliances and oasis societies. Separation from eastern rulers was gradual. 657 marks the defeat of a principal independent ruler by Tang forces; local rulers, contested authority and related confederations continued afterward.","wikiTitle":"Western Turkic Khaganate","sources":["regional_steppe_arabia_turk_unesco","regional_steppe_arabia_turk_washington","regional_steppe_arabia_turk_phd","wikipedia_rx-western-turkic"],"collections":["centralasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Western Turkic Khaganate","url":"https://en.wikipedia.org/wiki/Western_Turkic_Khaganate","pageid":7236467}},{"id":"rx-second-turkic","title":"Second Turkic Khaganate","region":"centralasia","dates":"c. 682–744 AD","start":682,"end":744,"category":"history","location":"Mongolian plateau · Inner Asia","note":"Restored Türk imperial rule developed after rebellion against Tang dominance. A coalition including Uyghur, Basmil and Karluk forces overthrew the khaganate; final resistance continued beyond conventional 744. These are state phases, not the full history of Turkic-speaking peoples.","wikiTitle":"Second Turkic Khaganate","sources":["regional_steppe_arabia_turk_second","regional_steppe_arabia_turk_unesco","regional_steppe_arabia_turk_phd","wikipedia_rx-second-turkic"],"collections":["centralasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Second Turkic Khaganate","url":"https://en.wikipedia.org/wiki/Second_Turkic_Khaganate","pageid":31494739}},{"id":"rx-uyghur-khaganate","title":"Uyghur Khaganate · Orkhon empire","region":"centralasia","dates":"744–840 AD","start":744,"end":840,"category":"history","location":"Orkhon Valley and wider Mongolian plateau","note":"An imperial confederation centred on Karabalghasun interacted closely with Tang China. 840 marks the collapse of this steppe empire; Uyghur communities and later oasis kingdoms continued. It is distinct from those later kingdoms and from modern identities and borders.","wikiTitle":"Uyghur Khaganate","sources":["regional_steppe_arabia_uyghur_cambridge","regional_steppe_arabia_central_met","wikipedia_rx-uyghur-khaganate"],"collections":["centralasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Uyghur Khaganate","url":"https://en.wikipedia.org/wiki/Uyghur_Khaganate","pageid":5763473}},{"id":"rx-sogdian-networks","title":"Sogdian cities and merchant networks","region":"centralasia","dates":"c. 4th–8th centuries AD · selected cultural phase","start":300,"end":800,"category":"culture","location":"Sogdiana · present-day Uzbekistan and Tajikistan; networks across Asia","note":"Agriculture, urban centres, merchants and diasporic communities supported wide cultural exchange. This selected flourishing phase groups several cities and local powers rather than one empire. Sogdian history began earlier and transformations continued after these rounded century anchors.","wikiTitle":"Sogdia","sources":["regional_steppe_arabia_sogdian_si","regional_steppe_arabia_central_met","wikipedia_rx-sogdian-networks"],"collections":["centralasia"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Sogdia","url":"https://en.wikipedia.org/wiki/Sogdia","pageid":93965}},{"id":"rx-saba","title":"Saba / Sheba · South Arabian kingdom","region":"westasia","dates":"c. 8th century BC–3rd century AD","start":-800,"end":300,"category":"history","location":"Marib and Sirwah · present-day Yemen","note":"A selected broad phase of Sabaean political power linked irrigation agriculture, cities, sanctuaries and incense trade. UNESCO supplies the approximate range used here; other chronologies begin earlier. The wider Marib archaeological landscape remained active beyond this kingdom frame.","wikiTitle":"Sheba","sources":["regional_steppe_arabia_saba_unesco","regional_steppe_arabia_arabia_met","wikipedia_rx-saba"],"collections":["westasia","arabia-caucasus"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Sheba","url":"https://en.wikipedia.org/wiki/Sheba","pageid":69270}},{"id":"rx-himyar","title":"Himyar · pre-Aksumite ruling phase","region":"westasia","dates":"c. 1st century BC–525 AD","start":-100,"end":525,"category":"history","location":"Southern Arabian highlands · present-day Yemen","note":"A southern Arabian kingdom expanded among neighbouring states and adopted royal monotheism in late antiquity. The approximate starting anchor selects a later portion of its early development; 525 marks Aksumite intervention, not the end of South Arabian society.","wikiTitle":"Himyar","sources":["regional_steppe_arabia_arabia_met","regional_steppe_arabia_himyar_research","wikipedia_rx-himyar"],"collections":["westasia","arabia-caucasus"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Himyar","url":"https://en.wikipedia.org/wiki/Himyar","pageid":717088}},{"id":"rx-nabataea","title":"Nabataean kingdom · royal phase","region":"westasia","dates":"c. 168 BC–106 AD · selected royal frame","start":-168,"end":106,"category":"history","location":"Petra, Hegra and surrounding northern Arabia / southern Levant","note":"Petra Museum dates this royal frame to 168 BC–106 AD. Nabataean communities and Petra existed earlier. Roman annexation in 106 ended the independent kingdom while settlements, language and traditions continued under changing rule.","wikiTitle":"Nabataean Kingdom","sources":["regional_steppe_arabia_nabataea_museum","regional_steppe_arabia_nabataea_roman","wikipedia_rx-nabataea"],"collections":["westasia","arabia-caucasus"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Nabataean Kingdom","url":"https://en.wikipedia.org/wiki/Nabataean_Kingdom","pageid":18582314}},{"id":"rx-first-saudi","title":"First Saudi state · Diriyah","region":"westasia","dates":"1727/1744–1818 AD","start":1727,"end":1818,"category":"history","location":"Diriyah and changing territories of the Arabian Peninsula","note":"1727 marks Muhammad bin Saud’s accession and the official Saudi founding convention. 1744 marks Ibn Abd al-Wahhab’s move to Diriyah and their religious-political alliance, often used as a founding date in historical writing. Ottoman-Egyptian forces captured Diriyah in 1818.","wikiTitle":"First Saudi state","sources":["regional_steppe_arabia_saudi_first","regional_steppe_arabia_saudi_founder","wikipedia_rx-first-saudi"],"collections":["westasia","arabia-caucasus"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"First Saudi state","url":"https://en.wikipedia.org/wiki/First_Saudi_state","pageid":757334}},{"id":"rx-second-saudi","title":"Second Saudi state · Najd","region":"westasia","dates":"1824–1891 AD","start":1824,"end":1891,"category":"history","location":"Riyadh and Najd · Arabian Peninsula","note":"Saudi rule was restored from Riyadh after an interruption following the fall of Diriyah. Civil conflict and changing territorial control marked this state; Rashidi ascendancy ended it in 1891. It was not uninterrupted rule over the boundaries of today’s Saudi Arabia.","wikiTitle":"Second Saudi state","sources":["regional_steppe_arabia_saudi_second","wikipedia_rx-second-saudi"],"collections":["westasia","arabia-caucasus"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Second Saudi state","url":"https://en.wikipedia.org/wiki/Second_Saudi_state","pageid":2361176}},{"id":"rx-saudi-unification","title":"Saudi expansion and unification","region":"westasia","dates":"1902–1932 AD · selected formation period","start":1902,"end":1932,"category":"period","location":"Riyadh, Najd, al-Ahsa, Hejaz and neighbouring Arabian territories","note":"A formation period from Ibn Saud’s capture of Riyadh to proclamation of Saudi Arabia. Several emirate, sultanate and dual-monarchy arrangements fall within it, including the existing Hejaz–Nejd entry. This groups campaigns and state changes rather than implying a single unchanged state since 1902.","wikiTitle":"Unification of Saudi Arabia","sources":["regional_steppe_arabia_saudi_unification","wikipedia_rx-saudi-unification"],"collections":["westasia","arabia-caucasus"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Unification of Saudi Arabia","url":"https://en.wikipedia.org/wiki/Unification_of_Saudi_Arabia","pageid":15860133}},{"id":"rx-urartu","title":"Urartu / Kingdom of Van","region":"westasia","dates":"c. 850–585 BC · broad kingdom frame","start":-850,"end":-585,"category":"history","location":"Armenian Highlands · Lake Van, eastern Anatolia and southern Caucasus","note":"A powerful kingdom developed around Lake Van and built fortified centres across the highlands. Its origins and collapse are approximate; this follows the History Museum of Armenia’s broad chronology. Shared territory with later Armenia does not establish a simple ethnic or political succession to any modern state.","wikiTitle":"Urartu","sources":["regional_steppe_arabia_urartu_museum","wikipedia_rx-urartu"],"collections":["westasia","arabia-caucasus"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Urartu","url":"https://en.wikipedia.org/wiki/Urartu","pageid":22216191}},{"id":"rx-arsacid-armenia","title":"Arsacid Armenia · royal period","region":"westasia","dates":"66–428 AD · selected dynastic frame","start":66,"end":428,"category":"history","location":"Armenian Highlands · between Roman and Iranian spheres","note":"The conventional period of Arsacid royal rule includes contested authority, outside intervention and partition. The dynasty’s end in 428 in the Persian sector did not end Armenian society, churches or language. Earlier Armenian kingdoms lie outside this selected frame.","wikiTitle":"Arsacid dynasty of Armenia","sources":["regional_steppe_arabia_armenia_ysu","regional_steppe_arabia_armenia_met","wikipedia_rx-arsacid-armenia"],"collections":["westasia","arabia-caucasus"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Arsacid dynasty of Armenia","url":"https://en.wikipedia.org/wiki/Arsacid_dynasty_of_Armenia","pageid":3637298}},{"id":"rx-bagratid-armenia","title":"Bagratid Armenian kingdom","region":"westasia","dates":"884/885–1045 AD","start":885,"end":1045,"category":"history","location":"Armenian Highlands · later capital at Ani","note":"Ashot I’s recognition restored Armenian kingship; sources differ between 884 and 885. Ani became the capital in 961. The end of the principal Bagratid kingdom did not end other Armenian kingdoms or communities, and medieval Armenia should not be read through today’s borders.","wikiTitle":"Bagratid Armenia","sources":["regional_steppe_arabia_bagratid_museum","regional_steppe_arabia_armenia_ysu","wikipedia_rx-bagratid-armenia"],"collections":["westasia","arabia-caucasus"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Bagratid Armenia","url":"https://en.wikipedia.org/wiki/Bagratid_Armenia","pageid":16954537}},{"id":"rx-cilician-armenia","title":"Cilician Armenia · principality and kingdom","region":"westasia","dates":"1080–1375 AD · kingdom from 1198/99","start":1080,"end":1375,"category":"history","location":"Cilicia · northeastern Mediterranean coast, present-day Türkiye","note":"An Armenian principality developed in Cilicia, outside the Armenian Highlands; royal coronation followed in 1198/99. Its court linked Mediterranean and Mongol worlds. The Mamluk capture of Sis in 1375 ended the kingdom, while Armenian communities and cultural traditions continued.","wikiTitle":"Armenian Kingdom of Cilicia","sources":["regional_steppe_arabia_cilicia_museum","regional_steppe_arabia_armenia_met","wikipedia_rx-cilician-armenia"],"collections":["westasia","arabia-caucasus"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Armenian Kingdom of Cilicia","url":"https://en.wikipedia.org/wiki/Armenian_Kingdom_of_Cilicia","pageid":1118477}},{"id":"rx-georgian-kingdom","title":"Kingdom of Georgia · medieval royal frame","region":"westasia","dates":"c. 1008–1490 AD · interrupted unity","start":1008,"end":1490,"category":"history","location":"Southern Caucasus · changing territory around present-day Georgia","note":"Bagrat III’s consolidation began a medieval royal formation whose reach changed substantially. Later invasions, subordinate rule, fragmentation and reunification prevent treating the span as continuous centralized control. By 1490 several kingdoms and principalities were recognised; Georgian history continued in them.","wikiTitle":"Kingdom of Georgia","sources":["regional_steppe_arabia_georgia_gnta","regional_steppe_arabia_georgia_royal","wikipedia_rx-georgian-kingdom"],"collections":["westasia","arabia-caucasus"],"regionalOnly":true,"status":"Selected","wikipedia":{"title":"Kingdom of Georgia","url":"https://en.wikipedia.org/wiki/Kingdom_of_Georgia","pageid":7466162}}];
